class Solution {
    public int[][] vertexDegree(List<List<Integer>> adj, boolean directed) {
        int n = adj.size();
        int[] inDeg = new int[n];
        int[] outDeg = new int[n];

        for (int u = 0; u < n; u++) {
            outDeg[u] = adj.get(u).size();
            if (directed) {
                for (int v : adj.get(u)) {
                    inDeg[v]++;
                }
            } else {
                inDeg[u] = outDeg[u];
            }
        }

        int[][] result = new int[2][n];
        result[0] = inDeg;
        result[1] = outDeg;
        return result;
    }
}

