import java.util.Arrays;

class Solution {
    public boolean hasCycle(List<List<Integer>> adj) {
        int n = adj.size();
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!visited[i] && dfs(i, -1, adj, visited)) {
                return true;
            }
        }
        return false;
    }

    private boolean dfs(int u, int p, List<List<Integer>> adj, boolean[] visited) {
        visited[u] = true;
        for (int v : adj.get(u)) {
            if (!visited[v]) {
                if (dfs(v, u, adj, visited)) return true;
            } else if (v != p) {
                return true;
            }
        }
        return false;
    }
}

