import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int largestRectangleArea(int[] heights) {
        Stack<Integer> stack = new Stack<>();
        stack.push(-1);
        int maxArea = 0;
        int[] extendedHeights = Arrays.copyOf(heights, heights.length + 1);
        extendedHeights[heights.length] = 0;

        for (int i = 0; i < extendedHeights.length; i++) {
            int h = extendedHeights[i];
            while (stack.peek() != -1 && extendedHeights[stack.peek()] >= h) {
                int height = extendedHeights[stack.pop()];
                int width = i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }

        return maxArea;
    }
}

