class Solution {
    public String alienOrder(String[] words) {
        Map<Character, Set<Character>> adj = new HashMap<>();
        Map<Character, Integer> indeg = new HashMap<>();

        for (String w : words) {
            for (char c : w.toCharArray()) {
                adj.putIfAbsent(c, new HashSet<>());
                indeg.putIfAbsent(c, 0);
            }
        }

        for (int i = 0; i < words.length - 1; i++) {
            String w1 = words[i];
            String w2 = words[i+1];
            int len = Math.min(w1.length(), w2.length());
            boolean foundDiff = false;

            for (int j = 0; j < len; j++) {
                char x = w1.charAt(j);
                char y = w2.charAt(j);
                if (x != y) {
                    if (!adj.get(x).contains(y)) {
                        adj.get(x).add(y);
                        indeg.put(y, indeg.get(y) + 1);
                    }
                    foundDiff = true;
                    break;
                }
            }
            if (!foundDiff && w1.length() > w2.length()) return "";
        }

        Queue<Character> q = new LinkedList<>();
        for (char c : indeg.keySet()) {
            if (indeg.get(c) == 0) q.offer(c);
        }

        StringBuilder order = new StringBuilder();
        while (!q.isEmpty()) {
            char u = q.poll();
            order.append(u);

            for (char v : adj.get(u)) {
                indeg.put(v, indeg.get(v) - 1);
                if (indeg.get(v) == 0) q.offer(v);
            }
        }

        return order.length() == indeg.size() ? order.toString() : "";
    }
}

