import java.util.Arrays;
import java.util.AbstractMap.SimpleEntry;
import java.util.Comparator;

class Solution {
    public int[] dijkstra(int V, List<List<SimpleEntry<Integer, Integer>>> adj, int src) {
        int[] dist = new int[V];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;

        PriorityQueue<SimpleEntry<Integer, Integer>> pq = new PriorityQueue<>(Comparator.comparingInt(SimpleEntry::getKey));
        pq.offer(new SimpleEntry<>(0, src));

        while (!pq.isEmpty()) {
            SimpleEntry<Integer, Integer> entry = pq.poll();
            int d = entry.getKey();
            int u = entry.getValue();

            if (d > dist[u]) continue;

            for (SimpleEntry<Integer, Integer> neighbor : adj.get(u)) {
                int v = neighbor.getKey();
                int w = neighbor.getValue();
                if (dist[u] != Integer.MAX_VALUE && d + w < dist[v]) {
                    dist[v] = d + w;
                    pq.offer(new SimpleEntry<>(dist[v], v));
                }
            }
        }
        return dist;
    }
}

