import java.util.List;
import java.util.Stack;
import java.util.Arrays;
import java.util.AbstractMap.SimpleEntry;

class Solution {
    public int[] shortestPathDAG(int V, List<List<SimpleEntry<Integer, Integer>>> adj, int src) {
        Stack<Integer> stack = new Stack<>();
        boolean[] visited = new boolean[V];
        for (int i = 0; i < V; i++) {
            if (!visited[i]) {
                topoSortDfs(i, adj, visited, stack);
            }
        }

        int[] dist = new int[V];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            if (dist[u] != Integer.MAX_VALUE) {
                for (SimpleEntry<Integer, Integer> neighbor : adj.get(u)) {
                    int v = neighbor.getKey();
                    int w = neighbor.getValue();
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                    }
                }
            }
        }
        return dist;
    }

    private void topoSortDfs(int u, List<List<SimpleEntry<Integer, Integer>>> adj, boolean[] visited, Stack<Integer> stack) {
        visited[u] = true;
        for (SimpleEntry<Integer, Integer> neighbor : adj.get(u)) {
            int v = neighbor.getKey();
            if (!visited[v]) {
                topoSortDfs(v, adj, visited, stack);
            }
        }
        stack.push(u);
    }
}

