class KQueues {
    private int n, k;
    private int[] arr;
    private int[] front;
    private int[] rear;
    private int[] next;
    private int free;

    public KQueues(int k, int n) {
        this.k = k;
        this.n = n;
        this.arr = new int[n];
        this.front = new int[k];
        this.rear = new int[k];
        this.next = new int[n];

        for (int i = 0; i < k; i++) front[i] = -1;
        for (int i = 0; i < k; i++) rear[i] = -1;
        for (int i = 0; i < n - 1; i++) next[i] = i + 1;
        next[n - 1] = -1;
        this.free = 0;
    }

    public boolean isEmpty(int qn) {
        return front[qn] == -1;
    }

    public boolean isFull() {
        return free == -1;
    }

    public void enqueue(int item, int qn) {
        if (isFull()) {
            System.out.println("Queue Overflow");
            return;
        }

        int newSlot = free;
        free = next[newSlot];

        if (isEmpty(qn)) {
            front[qn] = newSlot;
        } else {
            next[rear[qn]] = newSlot;
        }

        rear[qn] = newSlot;
        next[newSlot] = -1;
        arr[newSlot] = item;
    }

    public int dequeue(int qn) {
        if (isEmpty(qn)) {
            System.out.println("Queue Underflow");
            return Integer.MIN_VALUE;
        }

        int slotToFree = front[qn];
        front[qn] = next[slotToFree];

        next[slotToFree] = free;
        free = slotToFree;

        return arr[slotToFree];
    }
}

