import java.util.List;
import java.util.PriorityQueue;
import java.util.Arrays;
import java.util.AbstractMap.SimpleEntry;
import java.util.Comparator;

class Solution {
    public int countPaths(int n, int[][] roads) {
        long MOD = 1000000007;
        List<List<SimpleEntry<Integer, Integer>>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());

        for (int[] road : roads) {
            adj.get(road[0]).add(new SimpleEntry<>(road[1], road[2]));
            adj.get(road[1]).add(new SimpleEntry<>(road[0], road[2]));
        }

        long[] dist = new long[n];
        long[] ways = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        ways[0] = 1;

        PriorityQueue<SimpleEntry<Long, Integer>> pq = new PriorityQueue<>(Comparator.comparingLong(SimpleEntry::getKey));
        pq.offer(new SimpleEntry<>(0L, 0));

        while (!pq.isEmpty()) {
            SimpleEntry<Long, Integer> entry = pq.poll();
            long d = entry.getKey();
            int u = entry.getValue();

            if (d > dist[u]) continue;

            for (SimpleEntry<Integer, Integer> neighbor : adj.get(u)) {
                int v = neighbor.getKey();
                int w = neighbor.getValue();

                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    ways[v] = ways[u];
                    pq.offer(new SimpleEntry<>(dist[v], v));
                } else if (d + w == dist[v]) {
                    ways[v] = (ways[v] + ways[u]) % MOD;
                }
            }
        }
        return (int) (ways[n - 1] % MOD);
    }
}

