import java.lang.Math;

class Solution {
    public int sumSubarrayMins(int[] arr) {
        int MOD = 1000000007;
        Stack<Integer> stack = new Stack<>();
        long result = 0;
        int n = arr.length;

        int[] extendedArr = new int[n + 2];
        for (int i = 0; i < n; i++) {
            extendedArr[i + 1] = arr[i];
        }
        extendedArr[0] = 0;
        extendedArr[n + 1] = 0;

        for (int i = 0; i < extendedArr.length; i++) {
            int num = extendedArr[i];
            while (!stack.isEmpty() && extendedArr[stack.peek()] > num) {
                int j = stack.pop();
                int k = stack.peek();
                long count = (long) (i - j) * (j - k);
                result = (result + (long)extendedArr[j] * count) % MOD;
            }
            stack.push(i);
        }

        return (int) result;
    }
}

