        int[] res = new int[n];
        Arrays.fill(res, -1);
        Stack<Integer> stack = new Stack<>();

        for (int i = 2 * n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && stack.peek() <= nums[i % n]) {
                stack.pop();
            }

            if (i < n) {
                if (!stack.isEmpty()) {
                    res[i] = stack.peek();
                }
            }

            stack.push(nums[i % n]);
        }

        return res;
    }
}

