class CustomStack {
    private int[] stack;
    private int[] inc;
    private int size;
    private int maxSize;

    public CustomStack(int maxSize) {
        this.maxSize = maxSize;
        this.stack = new int[maxSize];
        this.inc = new int[maxSize];
        this.size = 0;
    }

    public void push(int x) {
        if (size < maxSize) {
            stack[size] = x;
            inc[size] = 0;
            size++;
        }
    }

    public int pop() {
        if (size == 0) return -1;
        size--;
        int increment = inc[size];
        if (size > 0) {
            inc[size - 1] += increment;
        }
        return stack[size] + increment;
    }

    public void increment(int k, int val) {
        int index = Math.min(k, size) - 1;
        if (index >= 0) {
            inc[index] += val;
        }
    }
}

