import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

class Solution {
    private int time;
    private int[] disc;
    private int[] low;
    private int[] ap;
    private List<List<Integer>> graph;

    public List<Integer> articulationPoints(int n, int[][] edges) {
        graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        disc = new int[n];
        low = new int[n];
        ap = new int[n];
        Arrays.fill(disc, -1);
        Arrays.fill(low, -1);
        time = 0;

        for (int i = 0; i < n; i++) {
            if (disc[i] == -1) {
                dfs(i, -1);
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (ap[i] == 1) result.add(i);
        }
        return result;
    }

    private void dfs(int u, int p) {
        disc[u] = low[u] = time++;
        int children = 0;

        for (int v : graph.get(u)) {
            if (v == p) continue;
            if (disc[v] != -1) {
                low[u] = Math.min(low[u], disc[v]);
            } else {
                children++;
                dfs(v, u);
                low[u] = Math.min(low[u], low[v]);

                if (p != -1 && low[v] >= disc[u]) {
                    ap[u] = 1;
                }
            }
        }

        if (p == -1 && children > 1) {
            ap[u] = 1;
        }
    }
}

