class Solution {
    public String reverseParentheses(String s) {
        int n = s.length();
        int[] portal = new int[n];
        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);
            } else if (s.charAt(i) == ')') {
                int j = stack.pop();
                portal[i] = j;
                portal[j] = i;
            }
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int direction = 1;
        while (i < n) {
            char c = s.charAt(i);
            if (c == '(' || c == ')') {
                i = portal[i];
                direction = -direction;
            } else {
                result.append(c);
            }
            i += direction;
        }

        return result.toString();
    }
}

