import java.util.List;
import java.util.ArrayList;
import java.util.Stack;
import java.util.Collections;
import java.util.Arrays;

class Solution {
    public List<List<Integer>> kosaraju(int V, List<List<Integer>> adj) {
        int[] vis = new int[V];
        Stack<Integer> st = new Stack<>();

        for (int i = 0; i < V; i++) {
            if (vis[i] == 0) dfs(i, adj, vis, st);
        }

        List<List<Integer>> rev = new ArrayList<>();
        for (int i = 0; i < V; i++) rev.add(new ArrayList<>());
        for (int u = 0; u < V; u++) {
            for (int v : adj.get(u)) {
                rev.get(v).add(u);
            }
        }

        Arrays.fill(vis, 0);
        List<List<Integer>> comps = new ArrayList<>();

        while (!st.isEmpty()) {
            int u = st.pop();
            if (vis[u] == 0) {
                List<Integer> comp = new ArrayList<>();
                dfs2(u, rev, vis, comp);
                comps.add(comp);
            }
        }
        return comps;
    }

    private void dfs(int u, List<List<Integer>> adj, int[] vis, Stack<Integer> st) {
        vis[u] = 1;
        for (int v : adj.get(u)) {
            if (vis[v] == 0) dfs(v, adj, vis, st);
        }
        st.push(u);
    }

    private void dfs2(int u, List<List<Integer>> rev, int[] vis, List<Integer> comp) {
        vis[u] = 1;
        comp.add(u);
        for (int v : rev.get(u)) {
            if (vis[v] == 0) dfs2(v, rev, vis, comp);
        }
    }
}

