class Solution {
    public int[] canSeePersonsCount(int[] heights) {
        int n = heights.length;
        int[] answer = new int[n];
        Stack<Integer> stack = new Stack<>();

        for (int i = n - 1; i >= 0; i--) {
            int h = heights[i];
            int count = 0;
            while (!stack.isEmpty() && h > stack.peek()) {
                stack.pop();
                count++;
            }
            if (!stack.isEmpty()) {
                count++;
            }
            answer[i] = count;
            stack.push(h);
        }
        return answer;
    }
}

