import java.lang.Math;

class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) prefixSum[i+1] = prefixSum[i] + nums[i];

        int[] maxLBefore = new int[n];
        int[] maxMBefore = new int[n];
        int currentMaxL = 0;
        int currentMaxM = 0;

        for (int i = 0; i < n; i++) {
            if (i >= firstLen - 1) {
                currentMaxL = Math.max(currentMaxL, prefixSum[i + 1] - prefixSum[i - firstLen + 1]);
            }
            maxLBefore[i] = currentMaxL;
            if (i >= secondLen - 1) {
                currentMaxM = Math.max(currentMaxM, prefixSum[i + 1] - prefixSum[i - secondLen + 1]);
            }
            maxMBefore[i] = currentMaxM;
        }

        int[] maxLAfter = new int[n];
        int[] maxMAfter = new int[n];
        currentMaxL = 0;
        currentMaxM = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (i <= n - firstLen) {
                currentMaxL = Math.max(currentMaxL, prefixSum[i + firstLen] - prefixSum[i]);
            }
            maxLAfter[i] = currentMaxL;
            if (i <= n - secondLen) {
                currentMaxM = Math.max(currentMaxM, prefixSum[i + secondLen] - prefixSum[i]);
            }
            maxMAfter[i] = currentMaxM;
        }

        int result = 0;
        for (int i = 0; i < n - 1; i++) {
            result = Math.max(result, maxLBefore[i] + maxMAfter[i + 1]);
            result = Math.max(result, maxMBefore[i] + maxLAfter[i + 1]);
        }
        return result;
    }
}

