import java.util.List;
import java.util.ArrayList;
import java.util.Set;
import java.util.HashSet;
import java.util.Arrays;
import java.util.stream.Collectors;

class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> wordSet = new HashSet<>(wordDict);
        int n = s.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && wordSet.contains(s.substring(j, i))) {
                    dp[i] = true;
                    break;
                }
            }
        }

        List<String> res = new ArrayList<>();
        if (!dp[n]) return res;

        backtrack(s, n, wordSet, new ArrayList<>(), res, dp);
        return res;
    }

    private void backtrack(String s, int start, Set<String> wordSet, List<String> path, List<String> res, boolean[] dp) {
        if (start == 0) {
            res.add(String.join(" ", path));
            return;
        }
        for (int end = start; end >= 1; end--) {
            String sub = s.substring(end - 1, start);
            if (wordSet.contains(sub)) {
                if (end > 0 && dp[end-1]) {
                     path.add(0, sub);
                     backtrack(s, end - 1, wordSet, path, res, dp);
                     path.remove(0);
                }
            }
        }
    }
}

