import java.lang.Math;

class Solution {
    public int numOfArrays(int n, int m, int k) {
        long MOD = 1000000000 + 7;
        long[][] dp = new long[n + 1][k + 1];

        for (int num = 1; num <= m; num++) {
            dp[1][1] = 1;
        }

        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int num = 1; num <= m; num++) {
                    // Case 1: num is the new max
                    if (j > 0) {
                        dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % MOD;
                    }
                    // Case 2: num is NOT the max (num-1 smaller choices)
                    dp[i][j] = (dp[i][j] + (dp[i-1][j] * (num - 1)) % MOD) % MOD;
                }
            }
        }

        long result = 0;
        for (int num = 1; num <= m; num++) {
            result = (result + dp[n][k]) % MOD;
        }
        return (int) result;
    }
}

