class Solution {
    public int minCost(int[] houses, int[][] cost, int m, int n, int target) {
        int INF = 1000000000;
        int[][][] dp = new int[m + 1][target + 1][n + 1];
        for (int i = 0; i <= m; i++)
            for (int j = 0; j <= target; j++)
                Arrays.fill(dp[i][j], INF);

        dp[0][0][0] = 0;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= Math.min(i, target); j++) {
