class MovingAverage {
    private Deque<Integer> q;
    private int size;
    private double windowSum;

    public MovingAverage(int size) {
        this.size = size;
        this.q = new LinkedList<>();
        this.windowSum = 0;
    }

    public double next(int val) {
        q.offerLast(val);
        windowSum += val;

        if (q.size() > size) {
            windowSum -= q.pollFirst();
        }

        return windowSum / q.size();
    }
}

