        max_next = 0
        for new_c1 in (c1-1, c1, c1+1):
            for new_c2 in (c2-1, c2, c2+1):
                max_next = max(max_next, helper(r+1, new_c1, new_c2))
        result += max_next
        dp[r][c1][c2] = result
        return result
