import java.util.Arrays;
import java.lang.Math;
import java.util.HashMap;
import java.util.Map;

class Solution {
    private int M, N;
    private int[][] Grid;
    private Integer[][][] memo;

    public int cherryPickup(int[][] grid) {
        M = grid.length;
        N = grid[0].length;
        Grid = grid;
        memo = new Integer[M][N][N];

        int result = helper(0, 0, N - 1);
        return Math.max(0, result);
    }

    private int helper(int r, int c1, int c2) {
        if (c1 < 0 || c1 >= N || c2 < 0 || c2 >= N) return Integer.MIN_VALUE / 2;

        if (r == M - 1) {
            return (c1 == c2) ? Grid[r][c1] : Grid[r][c1] + Grid[r][c2];
        }

        if (memo[r][c1][c2] != null) return memo[r][c1][c2];

        int result = (c1 == c2) ? Grid[r][c1] : Grid[r][c1] + Grid[r][c2];
        int maxNext = Integer.MIN_VALUE / 2;

        for (int newC1 = c1 - 1; newC1 <= c1 + 1; newC1++) {
            for (int newC2 = c2 - 1; newC2 <= c2 + 1; newC2++) {
                maxNext = Math.max(maxNext, helper(r + 1, newC1, newC2));
            }
        }

        result += maxNext;
        memo[r][c1][c2] = result;
        return result;
    }
}

