    count1 = collections.Counter(s1)
    count2 = collections.Counter(s2[:len1])

    if count1 == count2:
        return True

    for i in range(len1, len2):
        count2[s2[i]] += 1
        count2[s2[i - len1]] -= 1
        if count2[s2[i - len1]] == 0:
            del count2[s2[i - len1]]
        if count1 == count2:
            return True

    return False

