import java.util.Map;
import java.util.HashMap;
import java.lang.Math;

class Solution {
    public int maxNonOverlapping(int[] nums, int target) {
        int n = nums.length;
        int[] dp = new int[n + 1];
        Map<Integer, Integer> best = new HashMap<>();
        best.put(0, 0);
        int prefix = 0;

        for (int i = 1; i <= n; i++) {
            prefix += nums[i - 1];
            dp[i] = dp[i - 1];

            if (best.containsKey(prefix - target)) {
                dp[i] = Math.max(dp[i], best.get(prefix - target) + 1);
            }

            best.put(prefix, Math.max(best.getOrDefault(prefix, 0), dp[i]));
        }
        return dp[n];
    }
}

