class Solution {
    public int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;

        Queue<String> q = new LinkedList<>();
        q.offer("0000");
        Set<String> visited = new HashSet<>();
        visited.add("0000");
        int turns = 0;

        while (!q.isEmpty()) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
                String combo = q.poll();
                if (combo.equals(target)) return turns;

                char[] chars = combo.toCharArray();
                for (int j = 0; j < 4; j++) {
                    char original = chars[j];
                    for (int move : new int[]{1, -1}) {
                        int newDigit = (original - '0' + move + 10) % 10;
                        chars[j] = (char) (newDigit + '0');
                        String newCombo = String.valueOf(chars);

                        if (!visited.contains(newCombo) && !dead.contains(newCombo)) {
                            visited.add(newCombo);
                            q.offer(newCombo);
                        }
                    }
                    chars[j] = original;
                }
            }
            turns++;
        }
        return -1;
    }
}

