class Solution {
    public int numSquares(int n) {
        Queue<Integer> q = new LinkedList<>();
        q.offer(n);
        Set<Integer> visited = new HashSet<>();
        visited.add(n);
        int level = 0;

        List<Integer> squares = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            squares.add(i * i);
        }

        while (!q.isEmpty()) {
            level++;
            int size = q.size();
            for (int i = 0; i < size; i++) {
                int remainder = q.poll();
                for (int square : squares) {
                    int newRemainder = remainder - square;
                    if (newRemainder == 0) return level;
                    if (newRemainder < 0) break;
                    if (!visited.contains(newRemainder)) {
                        visited.add(newRemainder);
                        q.offer(newRemainder);
                    }
                }
            }
        }
        return 0;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public String minWindow(String s, String t) {
        if (t.isEmpty() || s.length() < t.length()) return "";

        Map<Character, Integer> tCounts = new HashMap<>();
        for (char c : t.toCharArray()) {
            tCounts.put(c, tCounts.getOrDefault(c, 0) + 1);
        }

        int required = tCounts.size();
        int formed = 0;
        int left = 0;
        int minLen = Integer.MAX_VALUE;
        int minStart = 0;
        Map<Character, Integer> windowCounts = new HashMap<>();

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            windowCounts.put(c, windowCounts.getOrDefault(c, 0) + 1);

            if (tCounts.containsKey(c) && windowCounts.get(c).intValue() == tCounts.get(c).intValue()) {
                formed++;
            }

            while (left <= right && formed == required) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minStart = left;
                }

                char leftChar = s.charAt(left);
                windowCounts.put(leftChar, windowCounts.get(leftChar) - 1);

                if (tCounts.containsKey(leftChar) && windowCounts.get(leftChar).intValue() < tCounts.get(leftChar).intValue()) {
                    formed--;
                }
                left++;
            }
        }

        return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
    }
}

