import java.util.Arrays;

class Solution {
    private int rows, cols;
    private int[][] heights;

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        if (heights == null || heights.length == 0) return new ArrayList<>();
        rows = heights.length;
        cols = heights[0].length;
        this.heights = heights;

        boolean[][] pacificReachable = new boolean[rows][cols];
        boolean[][] atlanticReachable = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            dfs(i, 0, pacificReachable);
            dfs(i, cols - 1, atlanticReachable);
        }
        for (int j = 0; j < cols; j++) {
            dfs(0, j, pacificReachable);
            dfs(rows - 1, j, atlanticReachable);
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (pacificReachable[r][c] && atlanticReachable[r][c]) {
                    result.add(Arrays.asList(r, c));
                }
            }
        }
        return result;
    }

    private void dfs(int r, int c, boolean[][] reachable) {
        if (reachable[r][c]) return;
        reachable[r][c] = true;

        int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && heights[nr][nc] >= heights[r][c]) {
                dfs(nr, nc, reachable);
            }
        }
    }
}

