class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) return null;

        Map<Node, Node> oldToNew = new HashMap<>();
        Queue<Node> q = new LinkedList<>();

        oldToNew.put(node, new Node(node.val));
        q.offer(node);

        while (!q.isEmpty()) {
            Node oldNode = q.poll();
            Node newNode = oldToNew.get(oldNode);

            for (Node oldNeighbor : oldNode.neighbors) {
                if (!oldToNew.containsKey(oldNeighbor)) {
                    Node newNeighbor = new Node(oldNeighbor.val);
                    oldToNew.put(oldNeighbor, newNeighbor);
                    q.offer(oldNeighbor);
                }
                newNode.neighbors.add(oldToNew.get(oldNeighbor));
            }
        }
        return oldToNew.get(node);
    }

    class Node {
        public int val;
        public List<Node> neighbors;
        public Node(int val) { this.val = val; neighbors = new ArrayList<Node>(); }
