        parts = filePath.split('/')[1:]
        node = self.root
        for part in parts[:-1]:
            if part not in node:
                node[part] = {}
            node = node[part]
        if parts[-1] not in node:
            node[parts[-1]] = "
        node[parts[-1]] += content

