    def deserialize(self, data):
        data = data.split(",")
        self.i = 0
        def build_tree():
            if self.i >= len(data) or data[self.i] == "#":
                self.i += 1
                return None

            node = TreeNode(int(data[self.i]))
            self.i += 1
            node.left = build_tree()
            node.right = build_tree()
            return node

