import java.util.regex.Pattern;

class Solution {
    private final String NEITHER = "Neither";
    private final String IPV4 = "IPv4";
    private final String IPV6 = "IPv6";

    public String validateIPAddress(String IP) {
        if (IP.contains(".")) {
            return validateIPv4(IP);
        } else if (IP.contains(":")) {
            return validateIPv6(IP);
        }
        return NEITHER;
    }

    private String validateIPv4(String IP) {
        String[] parts = IP.split("\\.", -1);
        if (parts.length != 4) return NEITHER;

        for (String part : parts) {
            if (part.isEmpty() || (part.length() > 1 && part.startsWith("0"))) return NEITHER;
            if (part.length() > 3) return NEITHER;

            for (char c : part.toCharArray()) {
                if (!Character.isDigit(c)) return NEITHER;
            }

            try {
                int val = Integer.parseInt(part);
                if (val < 0 || val > 255) return NEITHER;
            } catch (NumberFormatException e) {
                return NEITHER;
            }
        }
        return IPV4;
    }

    private String validateIPv6(String IP) {
        String[] parts = IP.split(":", -1);
        if (parts.length != 8) return NEITHER;

        for (String part : parts) {
            if (part.isEmpty() || part.length() > 4) return NEITHER;

            for (char c : part.toCharArray()) {
                boolean isHex = (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
                if (!isHex) return NEITHER;
            }
        }
        return IPV6;
    }
}

