        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                inDegree[leftChild[i]]++;
            }
            if (rightChild[i] != -1) {
                inDegree[rightChild[i]]++;
            }
        }

        int root = -1;
        int rootCount = 0;
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) {
                rootCount++;
                root = i;
            }
        }

        if (rootCount != 1) {
            return false;
        }

        Queue<Integer> queue = new LinkedList<>();
        queue.offer(root);
        Set<Integer> visited = new HashSet<>();
        visited.add(root);
        int visitedCount = 0;

        while (!queue.isEmpty()) {
            int node = queue.poll();
            visitedCount++;

            int leftNode = leftChild[node];
            int rightNode = rightChild[node];

            if (leftNode != -1) {
                if (visited.contains(leftNode)) return false;
                visited.add(leftNode);
                queue.offer(leftNode);
            }

            if (rightNode != -1) {
                if (visited.contains(rightNode)) return false;
                visited.add(rightNode);
                queue.offer(rightNode);
            }
        }

        return visitedCount == n;
    }
