class Solution {
    public int shortestDistance(int[][] grid) {
        if (grid == null || grid.length == 0) return -1;
        int m = grid.length;
        int n = grid[0].length;

        int[][] distanceSum = new int[m][n];
        int[][] reachCount = new int[m][n];
        int numBuildings = 0;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    numBuildings++;
                    bfs(grid, r, c, distanceSum, reachCount);
                }
            }
        }

        int minDist = Integer.MAX_VALUE;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0 && reachCount[r][c] == numBuildings) {
                    minDist = Math.min(minDist, distanceSum[r][c]);
                }
            }
        }

        return minDist == Integer.MAX_VALUE ? -1 : minDist;
    }

    private void bfs(int[][] grid, int startR, int startC, int[][] distSum, int[][] reachCount) {
        int m = grid.length;
        int n = grid[0].length;
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startR, startC, 0});
        boolean[][] visited = new boolean[m][n];
        visited[startR][startC] = true;

        int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            int[] pos = queue.poll();
            int r = pos[0];
            int c = pos[1];
            int dist = pos[2];

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0 && !visited[nr][nc]) {
                    distSum[nr][nc] += dist + 1;
                    reachCount[nr][nc]++;
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc, dist + 1});
                }
            }
        }
    }
}

class Solution {
