import java.util.Map;

class Solution {
    public int maxSubArrayLen(int[] nums, int k) {
        Map<Integer, Integer> prefixSums = new HashMap<>();
        prefixSums.put(0, -1);
        int currentSum = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            currentSum += nums[i];
            int complement = currentSum - k;
            if (prefixSums.containsKey(complement)) {
                maxLen = Math.max(maxLen, i - prefixSums.get(complement));
            }
            prefixSums.putIfAbsent(currentSum, i);
        }
        return maxLen;
    }
}

