class Solution {
    private final Map<Character, String> mapping = new HashMap<>() {{
        put('2', "abc");
        put('3', "def");
        put('4', "ghi");
        put('5', "jkl");
        put('6', "mno");
        put('7', "pqrs");
        put('8', "tuv");
        put('9', "wxyz");
    }};

    public List<String> letterCombinations(String digits) {
        if (digits.isEmpty()) return new ArrayList<>();
        List<String> result = new ArrayList<>();
        backtrack(0, digits, new StringBuilder(), result);
        return result;
    }

    private void backtrack(int index, String digits, StringBuilder path, List<String> result) {
        if (index == digits.length()) {
            result.add(path.toString());
            return;
        }

        String possibleLetters = mapping.get(digits.charAt(index));
        for (char letter : possibleLetters.toCharArray()) {
            path.append(letter);
            backtrack(index + 1, digits, path, result);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

class Solution {
    private int ROWS, COLS;
    private final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean exist(char[][] board, String word) {
        ROWS = board.length;
        COLS = board[0].length;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (dfs(r, c, 0, board, word)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfs(int r, int c, int index, char[][] board, String word) {
        if (index == word.length()) {
            return true;
        }
        if (r < 0 || r >= ROWS || c < 0 || c >= COLS || board[r][c] != word.charAt(index)) {
            return false;
        }

        char temp = board[r][c];
        board[r][c] = '#';

        boolean found = false;
        for (int[] dir : DIRS) {
            found = dfs(r + dir[0], c + dir[1], index + 1, board, word);
            if (found) break;
        }

        board[r][c] = temp;
        return found;
    }
}

