class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> res = new ArrayList<>();
        int i = 0;
        int n = words.length;

        while (i < n) {
            int lineStart = i;
            int lineLen = 0;
            List<String> lineWords = new ArrayList<>();
            int j = i;

            while (j < n && lineLen + words[j].length() + lineWords.size() <= maxWidth) {
                lineLen += words[j].length();
                lineWords.add(words[j]);
                j++;
            }

            int numWords = lineWords.size();
            int spacesNeeded = maxWidth - lineLen;
            StringBuilder line = new StringBuilder();

            if (j == n || numWords == 1) {
                for (int k = 0; k < numWords; k++) {
                    line.append(lineWords.get(k));
                    if (k < numWords - 1) {
                        line.append(" ");
                    }
                }
                while (line.length() < maxWidth) {
                    line.append(" ");
                }
            } 
            else {
                int numGaps = numWords - 1;
                int baseSpaces = spacesNeeded / numGaps;
                int extraSpaces = spacesNeeded % numGaps;

                for (int k = 0; k < numWords; k++) {
                    line.append(lineWords.get(k));
                    if (k < numGaps) {
                        for (int s = 0; s < baseSpaces; s++) {
                            line.append(" ");
                        }
                        if (k < extraSpaces) {
                            line.append(" ");
                        }
                    }
                }
            }

            res.add(line.toString());
            i = j;
        }
        return res;
    }
}

