    public int uniquePaths(int m, int n) {
        M = m;
        N = n;
        return dfs(0, 0);
    }

    private int dfs(int r, int c) {
        if (r == M - 1 && c == N - 1) return 1;
        if (r >= M || c >= N) return 0;

        String key = r + "," + c;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int paths = dfs(r + 1, c) + dfs(r, c + 1);
        memo.put(key, paths);
        return paths;
    }
}

