import collections

def find_min_height_trees(n, edges):
    if n <= 1:
        return [0]

    adj = collections.defaultdict(list)
    in_degree = [0] * n

    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
        in_degree[u] += 1
        in_degree[v] += 1

    leaves = collections.deque([i for i in range(n) if in_degree[i] == 1])
    remaining_nodes = n

    while remaining_nodes > 2:
        num_leaves = len(leaves)
        remaining_nodes -= num_leaves

        for _ in range(num_leaves):
            leaf = leaves.popleft()
            for neighbor in adj[leaf]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 1:
                    leaves.append(neighbor)

    return list(leaves)

