    }

    private boolean dp(int i, int j) {
        if (memo[i][j] != null) return memo[i][j];
        if (j == P.length()) return i == S.length();

        if (i == S.length()) {
            boolean result = P.charAt(j) == '*' && dp(i, j + 1);
            memo[i][j] = result;
            return result;
        }

        boolean result;
        if (P.charAt(j) == '?') {
            result = dp(i + 1, j + 1);
        } else if (P.charAt(j) == '*') {
            result = dp(i, j + 1) || dp(i + 1, j);
        } else {
            result = (S.charAt(i) == P.charAt(j)) && dp(i + 1, j + 1);
        }

        memo[i][j] = result;
        return result;
    }
}

class Solution {
    private int ROWS, COLS;
    private final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int numIslands(char[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        ROWS = grid.length;
        COLS = grid[0].length;
        int islandCount = 0;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (grid[r][c] == '1') {
                    islandCount++;
                    dfs(grid, r, c);
                }
            }
        }
        return islandCount;
    }

    private void dfs(char[][] grid, int r, int c) {
        if (r < 0 || c < 0 || r >= ROWS || c >= COLS || grid[r][c] == '0') {
            return;
        }
        grid[r][c] = '0';
        for (int[] dir : DIRS) {
            dfs(grid, r + dir[0], c + dir[1]);
        }
    }
}

class Solution {
    private int ROWS, COLS;
    private final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int maxAreaOfIsland(int[][] grid) {
        ROWS = grid.length;
        COLS = grid[0].length;
        int maxArea = 0;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (grid[r][c] == 1) {
                    maxArea = Math.max(maxArea, dfs(grid, r, c));
                }
            }
        }
        return maxArea;
    }

    private int dfs(int[][] grid, int r, int c) {
        if (r < 0 || c < 0 || r >= ROWS || c >= COLS || grid[r][c] == 0) {
            return 0;
        }

        grid[r][c] = 0;
        int area = 1;
        for (int[] dir : DIRS) {
            area += dfs(grid, r + dir[0], c + dir[1]);
        }
        return area;
    }
}

