class Solution {
    private Map<String, Integer> memo = new HashMap<>();
    private int[] Nums;
    private int Target;

    public int findTargetSumWays(int[] nums, int target) {
        Nums = nums;
        Target = target;
        return backtrack(0, 0);
    }

    private int backtrack(int index, int currentSum) {
        String key = index + "," + currentSum;
        if (memo.containsKey(key)) return memo.get(key);

        if (index == Nums.length) {
            return currentSum == Target ? 1 : 0;
        }

        int addPlus = backtrack(index + 1, currentSum + Nums[index]);
        int addMinus = backtrack(index + 1, currentSum - Nums[index]);

        int result = addPlus + addMinus;
        memo.put(key, result);
        return result;
    }
}

