class Solution {
    private Map<String, List<String>> graph;
    private Map<String, String> emailToName;
    private Set<String> visited;
    private List<List<String>> result;

    public List<List<String>> accountsMerge(List<List<String>> accounts) {
        graph = new HashMap<>();
        emailToName = new HashMap<>();

        for (List<String> acc : accounts) {
            String name = acc.get(0);
            String firstEmail = acc.get(1);
            emailToName.put(firstEmail, name);
            for (int i = 1; i < acc.size(); i++) {
                String email = acc.get(i);
                emailToName.put(email, name);
                graph.putIfAbsent(firstEmail, new ArrayList<>());
                graph.putIfAbsent(email, new ArrayList<>());
                graph.get(firstEmail).add(email);
                graph.get(email).add(firstEmail);
            }
        }

        visited = new HashSet<>();
        result = new ArrayList<>();

        for (String email : emailToName.keySet()) {
            if (!visited.contains(email)) {
                List<String> component = new ArrayList<>();
                dfs(email, component);
                Collections.sort(component);
                component.add(0, emailToName.get(email));
                result.add(component);
            }
        }
        return result;
    }

    private void dfs(String email, List<String> component) {
        visited.add(email);
        component.add(email);

        if (graph.containsKey(email)) {
            for (String neighbor : graph.get(email)) {
                if (!visited.contains(neighbor)) {
                    dfs(neighbor, component);
                }
            }
        }
    }
}

