import java.util.Arrays;

class Solution {
    private int count = 0;
    private boolean[] visited;
    private int N;

    public int countArrangement(int n) {
        this.N = n;
        visited = new boolean[n + 1];
        backtrack(1);
        return count;
    }

    private void backtrack(int index) {
        if (index > N) {
            count++;
            return;
        }

        for (int num = 1; num <= N; num++) {
            if (!visited[num] && (num % index == 0 || index % num == 0)) {
                visited[num] = true;
                backtrack(index + 1);
                visited[num] = false;
            }
        }
    }
}

