class Solution {
    private List<String> result = new ArrayList<>();
    private String S;

    public List<String> restoreIpAddresses(String s) {
        S = s;
        backtrack(0, new ArrayList<>());
        return result;
    }

    private void backtrack(int start_index, List<String> segments) {
        if (segments.size() == 4) {
            if (start_index == S.length()) {
                result.add(String.join(".", segments));
            }
            return;
        }

        for (int i = start_index; i < Math.min(start_index + 3, S.length()); i++) {
            String segment = S.substring(start_index, i + 1);
            if (isValidSegment(segment)) {
                segments.add(segment);
                backtrack(i + 1, segments);
                segments.remove(segments.size() - 1);
            }
        }
    }

    private boolean isValidSegment(String segment) {
        if (segment.length() > 1 && segment.startsWith("0")) return false;
        if (Integer.parseInt(segment) > 255) return false;
        return true;
    }
}

