            prev = prev.next;
        }

        ListNode curr = prev.next;
        ListNode subPrev = null;
        for (int i = 0; i < right - left + 1; i++) {
            ListNode nextTemp = curr.next;
            curr.next = subPrev;
            subPrev = curr;
