class Solution {
    public ListNode[] splitListToParts(ListNode head, int k) {
        int length = 0;
        ListNode curr = head;
        while (curr != null) {
            length++;
            curr = curr.next;
        }

        int partSize = length / k;
        int extraNodes = length % k;
        ListNode[] result = new ListNode[k];
        curr = head;

        for (int i = 0; i < k; i++) {
            result[i] = curr;
            int size = partSize + (extraNodes > 0 ? 1 : 0);
            extraNodes--;

            if (curr == null) continue;

            for (int j = 0; j < size - 1; j++) {
                curr = curr.next;
            }

            ListNode nextHead = curr.next;
            curr.next = null;
            curr = nextHead;
        }

        return result;
    }
}

