class Solution {
    public int[] nextLargerNodes(ListNode head) {
        List<Integer> nums = new ArrayList<>();
        ListNode curr = head;
        while (curr != null) {
            nums.add(curr.val);
            curr = curr.next;
        }

        int n = nums.size();
        int[] ans = new int[n];
        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i < n; i++) {
            int num = nums.get(i);
            while (!stack.isEmpty() && nums.get(stack.peek()) < num) {
                ans[stack.pop()] = num;
            }
            stack.push(i);
        }

        return ans;
    }
}

