class Solution {
    public ListNode removeZeroSumSublists(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        Map<Integer, ListNode> prefixSums = new HashMap<>();
        prefixSums.put(0, dummy);
        int currentSum = 0;
        ListNode curr = head;

        while (curr != null) {
            currentSum += curr.val;
            if (prefixSums.containsKey(currentSum)) {
                ListNode prev = prefixSums.get(currentSum);
                ListNode temp = prev.next;
                int tempSum = currentSum + temp.val;

                while (temp != curr) {
                    prefixSums.remove(tempSum);
                    temp = temp.next;
                    tempSum += temp.val;
                }
                prev.next = curr.next;
            } else {
                prefixSums.put(currentSum, curr);
            }
            curr = curr.next;
        }

        return dummy.next;
    }
}

