class LRUCache {
    class DLinkedNode {
        int key;
        int val;
        DLinkedNode prev;
        DLinkedNode next;
        DLinkedNode(int key, int val) { this.key = key; this.val = val; }
    }

    private Map<Integer, DLinkedNode> cache;
    private int capacity;
    private DLinkedNode head;
    private DLinkedNode tail;

    public LRUCache(int capacity) {
        this.cache = new HashMap<>();
        this.capacity = capacity;
        this.head = new DLinkedNode(0, 0);
        this.tail = new DLinkedNode(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    private void removeNode(DLinkedNode node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void addToFront(DLinkedNode node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    public int get(int key) {
        if (!cache.containsKey(key)) {
            return -1;
        }
        DLinkedNode node = cache.get(key);
        removeNode(node);
        addToFront(node);
        return node.val;
    }

    public void put(int key, int value) {
        if (cache.containsKey(key)) {
            DLinkedNode node = cache.get(key);
            node.val = value;
            removeNode(node);
            addToFront(node);
        } else {
            if (cache.size() == capacity) {
                DLinkedNode lru = tail.prev;
                cache.remove(lru.key);
                removeNode(lru);
            }
            DLinkedNode newNode = new DLinkedNode(key, value);
            cache.put(key, newNode);
            addToFront(newNode);
        }
    }
}

import java.util.HashMap;
import java.util.Map;

class LFUCache {
    class DLinkedNode {
        int key;
        int val;
        int freq;
        DLinkedNode prev;
        DLinkedNode next;
        DLinkedNode(int key, int val) { this.key = key; this.val = val; this.freq = 1; }
    }

    class DLinkedList {
        DLinkedNode head;
        DLinkedNode tail;
        int size;
        DLinkedList() {
            head = new DLinkedNode(0, 0);
            tail = new DLinkedNode(0, 0);
            head.next = tail;
            tail.prev = head;
            size = 0;
        }
        void add(DLinkedNode node) {
            node.next = head.next;
            node.prev = head;
            head.next.prev = node;
            head.next = node;
            size++;
        }
        void remove(DLinkedNode node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
            size--;
        }
        DLinkedNode removeTail() {
            DLinkedNode lru = tail.prev;
            remove(lru);
            return lru;
        }
    }

    Map<Integer, DLinkedNode> keyToNode;
    Map<Integer, DLinkedList> freqToList;
    int capacity;
    int minFreq;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.keyToNode = new HashMap<>();
        this.freqToList = new HashMap<>();
        this.minFreq = 0;
    }

    private void updateNode(DLinkedNode node) {
        DLinkedList oldList = freqToList.get(node.freq);
        oldList.remove(node);

        if (oldList.size == 0 && minFreq == node.freq) {
            minFreq++;
        }

        node.freq++;
        freqToList.putIfAbsent(node.freq, new DLinkedList());
        freqToList.get(node.freq).add(node);
    }

    public int get(int key) {
        if (!keyToNode.containsKey(key)) {
            return -1;
        }
        DLinkedNode node = keyToNode.get(key);
        updateNode(node);
        return node.val;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;

        if (keyToNode.containsKey(key)) {
            DLinkedNode node = keyToNode.get(key);
            node.val = value;
            updateNode(node);
        } else {
            if (keyToNode.size() == capacity) {
                DLinkedList lruList = freqToList.get(minFreq);
                DLinkedNode lruNode = lruList.removeTail();
                keyToNode.remove(lruNode.key);
            }

            DLinkedNode newNode = new DLinkedNode(key, value);
            keyToNode.put(key, newNode);

            freqToList.putIfAbsent(1, new DLinkedList());
            freqToList.get(1).add(newNode);
            minFreq = 1;
        }
    }
}

