class Solution {
    public List<int[]> findPairsWithSum(Node head, int target) {
        if (head == null) return new ArrayList<>();

        Node tail = head;
        while (tail.next != null) {
            tail = tail.next;
        }

        Node left = head;
        Node right = tail;
        List<int[]> result = new ArrayList<>();

        while (left != right && left.prev != right) {
            int currentSum = left.data + right.data;
            if (currentSum == target) {
                result.add(new int[]{left.data, right.data});
                left = left.next;
                right = right.prev;
            } else if (currentSum < target) {
                left = left.next;
            } else {
                right = right.prev;
            }
        }
        return result;
    }

    class Node {
        int data;
        Node prev;
        Node next;
    }
}

class Solution {
    public Node reverseList(Node head) {
        Node prev = null;
        Node curr = head;
        while (curr != null) {
            Node nextTemp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nextTemp;
        }
        return prev;
    }

    public Node compute(Node head) {
        Node reversedHead = reverseList(head);
        int maxSoFar = Integer.MIN_VALUE;
        Node curr = reversedHead;
        Node prev = null;

        while (curr != null) {
            if (curr.data >= maxSoFar) {
                maxSoFar = curr.data;
                prev = curr;
                curr = curr.next;
            } else {
                prev.next = curr.next;
                curr = prev.next;
            }
        }
        return reverseList(reversedHead);
    }

