class Solution {
    public List<int[]> findTriplets(Node head, int target) {
        if (head == null || head.next == null || head.next.next == null) return new ArrayList<>();

        List<int[]> result = new ArrayList<>();
        Node curr = head;
        Node tail = head;
        while (tail.next != null) {
            tail = tail.next;
        }

        while (curr != null) {
            Node left = curr.next;
            Node right = tail;
            int remainingSum = target - curr.data;

            while (left != null && right != null && left != right && right.next != left) {
                if (left.data + right.data == remainingSum) {
                    result.add(new int[]{curr.data, left.data, right.data});
                    left = left.next;
                    right = right.prev;
                } else if (left.data + right.data < remainingSum) {
                    left = left.next;
                } else {
                    right = right.prev;
                }
            }
            curr = curr.next;
        }
        return result;
    }

