class MyStack {
    class DLinkedNode {
        int val;
        DLinkedNode prev;
        DLinkedNode next;
        DLinkedNode(int val) { this.val = val; }
    }

    DLinkedNode head;
    DLinkedNode tail;
    int size;

    public MyStack() {
        head = new DLinkedNode(-1);
        tail = new DLinkedNode(-1);
        head.next = tail;
        tail.prev = head;
        size = 0;
    }

    public void push(int val) {
        DLinkedNode newNode = new DLinkedNode(val);

        newNode.next = head.next;
        newNode.prev = head;
        head.next.prev = newNode;
        head.next = newNode;

        size++;
    }

    public int pop() {
        if (size == 0) {
            throw new EmptyStackException();
        }
        DLinkedNode nodeToPop = head.next;
        head.next = nodeToPop.next;
        nodeToPop.next.prev = head;
        size--;
        return nodeToPop.val;
    }

    public int top() {
        if (size == 0) {
            throw new EmptyStackException();
        }
        return head.next.val;
    }

    public boolean isEmpty() {
        return size == 0;
    }
}

