            curr = curr.next;
        }

        if (n > length) {
            n = length;
        }

        Node startNode = head;
        for (int i = 0; i < length - n; i++) {
            startNode = startNode.next;
        }

        int totalSum = 0;
        curr = startNode;
        while (curr != null) {
            totalSum += curr.data;
            curr = curr.next;
        }

        return totalSum;
    }

