class Solution {
    public Node sort(Node head) {
        if (head == null || head.next == head) return head;

        Node linearHead = head;
        Node tail = head;
        while (tail.next != head) {
            tail = tail.next;
        }
        tail.next = null;

        Node mid = getMiddle(linearHead);
        Node rightHalf = mid.next;
        mid.next = null;

        Node leftSorted = sort(linearHead);
        Node rightSorted = sort(rightHalf);

        Node mergedLinear = merge(leftSorted, rightSorted);

        Node curr = mergedLinear;
        while (curr.next != null) {
            curr = curr.next;
        }
        curr.next = mergedLinear;
        return mergedLinear;
    }

    private Node getMiddle(Node node) {
        if (node == null) return node;
        Node slow = node;
        Node fast = node.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    private Node merge(Node left, Node right) {
        Node dummy = new Node(0);
        Node tail = dummy;
        while (left != null && right != null) {
            if (left.data < right.data) {
                tail.next = left;
                left = left.next;
            } else {
                tail.next = right;
                right = right.next;
            }
            tail = tail.next;
        }
        tail.next = (left != null) ? left : right;
        return dummy.next;
    }

    class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }
}

