        Node curr = head;

        while (curr != null) {
            if (curr.next != null && curr.data == curr.next.data) {
                int duplicateVal = curr.data;
                while (curr != null && curr.data == duplicateVal) {
                    curr = curr.next;
                }
                prev.next = curr;
                if (curr != null) {
                    curr.prev = prev;
                }
            } else {
                prev = curr;
                curr = curr.next;
            }
        }
        return dummy.next;
    }

    class Node {
        int data;
        Node prev;
        Node next;
        Node(int data) { this.data = data; }
    }
}

class Solution {
    public Node reverseKGroup(Node head, int k) {
        if (head == null || k == 1) return head;

        Node dummy = new Node(0);
        dummy.next = head;
        head.prev = dummy;

        Node prevGroupTail = dummy;
        Node curr = head;

        while (curr != null) {
            Node groupHead = curr;
            Node groupTail = curr;
            int count = 1;
            while (count < k && groupTail.next != null) {
                groupTail = groupTail.next;
                count++;
            }

            if (count < k) break;

            Node nextGroupHead = groupTail.next;

            groupTail.next = null;
            if (nextGroupHead != null) nextGroupHead.prev = null;

            Node tempCurr = groupHead;
            Node prev = null;
            while (tempCurr != null) {
                Node temp = tempCurr.next;
                tempCurr.next = tempCurr.prev;
                tempCurr.prev = temp;
                prev = tempCurr;
                tempCurr = temp;
            }

            Node newHead = prev;
            Node newTail = groupHead;

            prevGroupTail.next = newHead;
            newHead.prev = prevGroupTail;

            newTail.next = nextGroupHead;
            if (nextGroupHead != null) nextGroupHead.prev = newTail;

            prevGroupTail = newTail;
            curr = nextGroupHead;
        }
        return dummy.next;
    }

    class Node {
        int data;
        Node prev;
        Node next;
        Node(int data) { this.data = data; }
    }
}

