class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 1;
        for (int pile : piles) right = Math.max(right, pile);

        int minSpeed = right;

        while (left <= right) {
            int k = left + (right - left) / 2;
            long totalHours = 0;
            for (int pile : piles) {
                totalHours += (pile + k - 1) / k;
            }

            if (totalHours <= h) {
                minSpeed = k;
                right = k - 1;
            } else {
                left = k + 1;
            }
        }
        return minSpeed;
    }
}

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int sum = 0;
        int maxWeight = 0;
        for (int w : weights) {
            sum += w;
            maxWeight = Math.max(maxWeight, w);
        }

        int left = maxWeight;
        int right = sum;
        int minCapacity = sum;

        while (left <= right) {
            int capacity = left + (right - left) / 2;
            int daysNeeded = 1;
            int currentLoad = 0;

            for (int w : weights) {
                if (currentLoad + w > capacity) {
                    daysNeeded++;
                    currentLoad = w;
                } else {
                    currentLoad += w;
                }
            }

            if (daysNeeded <= days) {
                minCapacity = capacity;
                right = capacity - 1;
            } else {
                left = capacity + 1;
            }
        }
        return minCapacity;
    }
}

class Solution {
    public int splitArray(int[] nums, int m) {
