        for (int num : nums) {
            sum += num;
            maxNum = Math.max(maxNum, num);
        }

        int left = maxNum;
        int right = sum;
        int minMaxSum = sum;

        while (left <= right) {
            int maxSumAllowed = left + (right - left) / 2;
            int subarraysNeeded = 1;
            int currentSum = 0;

            for (int num : nums) {
                if (currentSum + num > maxSumAllowed) {
                    subarraysNeeded++;
                    currentSum = num;
                } else {
                    currentSum += num;
                }
            }

            if (subarraysNeeded <= m) {
                minMaxSum = maxSumAllowed;
                right = maxSumAllowed - 1;
            } else {
                left = maxSumAllowed + 1;
            }
        }
        return minMaxSum;
    }
}

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int[] A = nums1;
        int[] B = nums2;
        if (nums1.length > nums2.length) {
            A = nums2;
            B = nums1;
        }

        int m = A.length;
        int n = B.length;
        int total = m + n;
        int half = (total + 1) / 2;

        int left = 0;
        int right = m;

        while (left <= right) {
            int i = left + (right - left) / 2;
            int j = half - i;

            long Aleft = (i == 0) ? Long.MIN_VALUE : A[i - 1];
            long Aright = (i == m) ? Long.MAX_VALUE : A[i];
            long Bleft = (j == 0) ? Long.MIN_VALUE : B[j - 1];
            long Bright = (j == n) ? Long.MAX_VALUE : B[j];

            if (Aleft <= Bright && Bleft <= Aright) {
                if (total % 2 == 1) {
                    return Math.max(Aleft, Bleft);
                } else {
                    return (Math.max(Aleft, Bleft) + Math.min(Aright, Bright)) / 2.0;
                }
            } else if (Aleft > Bright) {
                right = i - 1;
            } else {
                left = i + 1;
            }
        }
        return 0.0;
    }
}

import java.util.List;
