class Solution {
    public int solve(int n, int k, int[] stalls) {
        Arrays.sort(stalls);
        int left = 1;
        int right = stalls[n - 1] - stalls[0];
        int maxMinDist = 0;

        while (left <= right) {
            int midDist = left + (right - left) / 2;
            int cowsPlaced = 1;
            int lastPos = stalls[0];

            for (int i = 1; i < n; i++) {
                if (stalls[i] - lastPos >= midDist) {
                    cowsPlaced++;
                    lastPos = stalls[i];
                }
            }

            if (cowsPlaced >= k) {
                maxMinDist = midDist;
                left = midDist + 1;
            } else {
                right = midDist - 1;
            }
        }
        return maxMinDist;
    }
}

