                }
            }

            if (studentsNeeded <= m) {
                minMaxPages = midPages;
                right = midPages - 1;
            } else {
                left = midPages + 1;
            }
        }
        return minMaxPages;
    }
}

class Solution {
    public int searchNearlySorted(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            }
            if (mid > left && nums[mid - 1] == target) {
                return mid - 1;
            }
            if (mid < right && nums[mid + 1] == target) {
                return mid + 1;
            }

            if (nums[mid] < target) {
                left = mid + 2;
            } else {
                right = mid - 2;
            }
        }
        return -1;
    }
}

