class Solution {
    public int smallestDivisor(int[] nums, int threshold) {
        int left = 1;
        int right = 0;
        for (int num : nums) right = Math.max(right, num);
        int ans = right;

        while (left <= right) {
            int midDivisor = left + (right - left) / 2;
            long totalSum = 0;

            for (int num : nums) {
                totalSum += (num + midDivisor - 1) / midDivisor;
            }

            if (totalSum <= threshold) {
                ans = midDivisor;
                right = midDivisor - 1;
            } else {
                left = midDivisor + 1;
            }
        }
