class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int left = 0;
        int right = arr.length - k;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (x - arr[mid] > arr[mid + k] - x) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return Arrays.stream(arr, left, left + k).boxed().collect(Collectors.toList());
    }
}

class Solution {
    public int search(int[] nums, int target) {
        return helper(nums, target, 0, nums.length - 1);
    }

    private int helper(int[] nums, int target, int left, int right) {
        if (left > right) {
            return -1;
        }

        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] < target) {
            return helper(nums, target, mid + 1, right);
        } else {
            return helper(nums, target, left, mid - 1);
        }
    }
}

class Solution {
    public int singleNonDuplicate(int[] nums) {
        int left = 0;
        int right = nums.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (mid % 2 == 1) {
                mid--;
            }

            if (nums[mid] == nums[mid + 1]) {
                left = mid + 2;
            } else {
                right = mid;
            }
        }
        return nums[left];
    }
}

class Solution {
    public int kthSmallest(int[][] matrix, int k) {
        int n = matrix.length;
        int left = matrix[0][0];
        int right = matrix[n - 1][n - 1];
        int ans = right;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (countLessEqual(matrix, mid) >= k) {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return ans;
    }

    private int countLessEqual(int[][] matrix, int val) {
        int n = matrix.length;
        int count = 0;
        int r = n - 1;
        int c = 0;
        while (r >= 0 && c < n) {
            if (matrix[r][c] <= val) {
                count += (r + 1);
                c++;
            } else {
                r--;
            }
        }
        return count;
    }
}

class Solution {
    public int NthRoot(int n, int m) {
        if (m == 1) return 1;
        int left = 1;
        int right = m;
        int ans = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            long val = 1;
            for (int i = 0; i < n; i++) {
                if (val > m / mid) {
                    val = m + 1;
                    break;
                }
                val *= mid;
            }

            if (val == m) {
                return mid;
            } else if (val < m) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int leftCol = 0;
        int rightCol = cols - 1;

        while (leftCol <= rightCol) {
            int midCol = leftCol + (rightCol - leftCol) / 2;
            int maxRow = 0;

            for (int r = 0; r < rows; r++) {
                if (mat[r][midCol] > mat[maxRow][midCol]) {
                    maxRow = r;
                }
            }

            int val = mat[maxRow][midCol];
            int leftVal = (midCol > 0) ? mat[maxRow][midCol - 1] : -1;
            int rightVal = (midCol < cols - 1) ? mat[maxRow][midCol + 1] : -1;

            if (val > leftVal && val > rightVal) {
                return new int[]{maxRow, midCol};
            } else if (val < leftVal) {
                rightCol = midCol - 1;
            } else {
                leftCol = midCol + 1;
            }
        }
        return new int[]{-1, -1};
    }
}

