            long rightCount = n - 1 - index;

            long totalSum = getSum(midVal - 1, (int) leftCount) + 
                            getSum(midVal - 1, (int) rightCount) + 
                            midVal;

            if (totalSum <= maxSum) {
                ans = midVal;
                left = midVal + 1;
            } else {
                right = midVal - 1;
            }
        }
        return ans;
    }
}

class Solution {
    public double minmaxGasDist(int[] stations, int k) {
        double left = 0.0;
        double right = stations[stations.length - 1] - stations[0];

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            int needed = 0;

            for (int j = 0; j < stations.length - 1; j++) {
                double gap = stations[j + 1] - stations[j];
                needed += Math.ceil(gap / mid) - 1;
            }

            if (needed <= k) {
                right = mid;
            } else {
                left = mid;
            }
        }
        return right;
    }
}

class Solution {
