class Solution {
    public int findInBitonic(int[] arr, int target) {
        int peak = findPeak(arr);
        int res = bsAscending(arr, 0, peak, target);
        if (res != -1) return res;
        return bsDescending(arr, peak + 1, arr.length - 1, target);
    }

    private int findPeak(int[] nums) {
        int left = 0;
        int right = nums.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < nums[mid + 1]) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private int bsAscending(int[] nums, int l, int r, int t) {
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] == t) return mid;
            else if (nums[mid] < t) l = mid + 1;
            else r = mid - 1;
        }
        return -1;
    }

    private int bsDescending(int[] nums, int l, int r, int t) {
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] == t) return mid;
            else if (nums[mid] < t) r = mid - 1;
            else l = mid + 1;
        }
        return -1;
    }
}

