class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        if ((long)m * k > bloomDay.length) return -1;

        int minDay = bloomDay[0];
        int maxDay = bloomDay[0];
        for (int day : bloomDay) {
            minDay = Math.min(minDay, day);
            maxDay = Math.max(maxDay, day);
        }

        int left = minDay;
        int right = maxDay;
        int ans = -1;

        while (left <= right) {
            int midDay = left + (right - left) / 2;
            int bouquets = 0;
            int flowers = 0;

            for (int day : bloomDay) {
                if (day <= midDay) {
                    flowers++;
                    if (flowers == k) {
                        bouquets++;
                        flowers = 0;
                    }
                } else {
                    flowers = 0;
                }
            }

            if (bouquets >= m) {
                ans = midDay;
                right = midDay - 1;
            } else {
                left = midDay + 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int minimumSize(int[] nums, int maxOperations) {
        int left = 1;
        int right = 0;
        for (int num : nums) right = Math.max(right, num);
        int ans = right;

        while (left <= right) {
            int midPenalty = left + (right - left) / 2;
            long opsNeeded = 0;

            for (int num : nums) {
                opsNeeded += (num - 1) / midPenalty;
            }

            if (opsNeeded <= maxOperations) {
                ans = midPenalty;
                right = midPenalty - 1;
            } else {
                left = midPenalty + 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int findKthNumber(int m, int n, int k) {
        int left = 1;
        int right = m * n;
        int ans = right;

        while (left <= right) {
            int midVal = left + (right - left) / 2;
            int count = 0;
            for (int i = 1; i <= m; i++) {
                count += Math.min(midVal / i, n);
            }

            if (count >= k) {
                ans = midVal;
                right = midVal - 1;
            } else {
                left = midVal + 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int[] kthSmallestPrimeFraction(int[] arr, int k) {
        double left = 0.0;
        double right = 1.0;
        int[] ans = new int[2];

        for (int iter = 0; iter < 100; iter++) {
            double mid = (left + right) / 2.0;
            int count = 0;
            double maxFraction = 0.0;
            int num = 0, den = 1;
            int j = 1;

            for (int i = 0; i < arr.length - 1; i++) {
                while (j < arr.length && arr[i] > mid * arr[j]) {
                    j++;
                }
                count += (arr.length - j);

                if (j < arr.length) {
                    double currentFraction = (double)arr[i] / arr[j];
                    if (currentFraction > maxFraction) {
                        maxFraction = currentFraction;
                        num = arr[i];
                        den = arr[j];
                    }
                }
            }

            if (count == k) {
                return new int[]{num, den};
            } else if (count < k) {
                left = mid;
            } else {
                right = mid;
            }
        }
        return ans;
    }
}

