class Solution {
    public int numMatchingSubsequences(String s, String[] words) {
        Map<Character, List<Integer>> charIndices = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            charIndices.putIfAbsent(s.charAt(i), new ArrayList<>());
            charIndices.get(s.charAt(i)).add(i);
        }

        int count = 0;
        for (String word : words) {
            int currentIndex = -1;
            boolean isSubsequence = true;
            for (char c : word.toCharArray()) {
                if (!charIndices.containsKey(c)) {
                    isSubsequence = false;
                    break;
                }

                List<Integer> indices = charIndices.get(c);
                int matchIdx = Collections.binarySearch(indices, currentIndex + 1);

                if (matchIdx < 0) {
                    matchIdx = -(matchIdx + 1);
                }

                if (matchIdx == indices.size()) {
                    isSubsequence = false;
                    break;
                } else {
                    currentIndex = indices.get(matchIdx);
                }
            }

            if (isSubsequence) {
                count++;
            }
        }
        return count;
    }
}

