class MyCalendar {
    private List<int[]> events;

    public MyCalendar() {
        events = new ArrayList<>();
    }

    public boolean book(int start, int end) {
        int[] newEvent = new int[]{start, end};
        int idx = Collections.binarySearch(events, newEvent, (a, b) -> Integer.compare(a[0], b[0]));

        if (idx < 0) {
            idx = -(idx + 1);
        }

        if (idx > 0 && events.get(idx - 1)[1] > start) {
            return false;
        }

        if (idx < events.size() && events.get(idx)[0] < end) {
            return false;
        }

        events.add(idx, newEvent);
        return true;
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    class Job {
        int start, end, profit;
        Job(int s, int e, int p) {
            this.start = s;
            this.end = e;
            this.profit = p;
        }
    }

    private Job[] jobs;
    private Map<Integer, Integer> memo;
    private int[] sortedStartTimes;
    private int n;

    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        n = startTime.length;
        jobs = new Job[n];
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(startTime[i], endTime[i], profit[i]);
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a.start, b.start));

        sortedStartTimes = new int[n];
        for(int i = 0; i < n; i++) sortedStartTimes[i] = jobs[i].start;
        memo = new HashMap<>();

        return dp(0);
    }

    private int dp(int i) {
        if (i == n) return 0;
        if (memo.containsKey(i)) return memo.get(i);

        int profitSkip = dp(i + 1);

        int currentEndTime = jobs[i].end;
        int nextJobIndex = Arrays.binarySearch(sortedStartTimes, i, n, currentEndTime);

        if (nextJobIndex < 0) {
            nextJobIndex = -(nextJobIndex + 1);
        }

        int profitTake = jobs[i].profit + dp(nextJobIndex);

        int maxProfit = Math.max(profitSkip, profitTake);
        memo.put(i, maxProfit);
        return maxProfit;
    }
}

