import java.util.Arrays;

class Solution {
    public boolean isMajorityElement(int[] nums, int target) {
        int n = nums.length;
        int firstIndex = findLowerBound(nums, target);

        if (firstIndex == n || nums[firstIndex] != target) {
            return false;
        }

        int majorityIndex = firstIndex + (n / 2);

        return (majorityIndex < n && nums[majorityIndex] == target);
    }

    private int findLowerBound(int[] nums, int target) {
        int left = 0;
        int right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

