import java.util.Collections;

class Solution {
    public int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int MOD = 1000000007;

        int[] sortedNums1 = Arrays.copyOf(nums1, n);
        Arrays.sort(sortedNums1);

        long totalDiff = 0;
        int maxGain = 0;

        for (int i = 0; i < n; i++) {
            int originalDiff = Math.abs(nums1[i] - nums2[i]);
            totalDiff = (totalDiff + originalDiff) % MOD;

            int target = nums2[i];
            int idx = Arrays.binarySearch(sortedNums1, target);
            if (idx < 0) {
                idx = -(idx + 1);
            }

            int newMinDiff = originalDiff;

            if (idx < n) {
                newMinDiff = Math.min(newMinDiff, Math.abs(sortedNums1[idx] - target));
            }
            if (idx > 0) {
                newMinDiff = Math.min(newMinDiff, Math.abs(sortedNums1[idx - 1] - target));
            }

            int gain = originalDiff - newMinDiff;
            maxGain = Math.max(maxGain, gain);
        }

        return (int) ((totalDiff - maxGain + MOD) % MOD);
    }
}

import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        List<Integer> sub = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int h = obstacles[i];

            int idx = Collections.binarySearch(sub, h);
            if (idx < 0) {
                idx = -(idx + 1);
            }

            if (idx == sub.size()) {
                sub.add(h);
            } else {
                sub.set(idx, h);
            }

            ans[i] = idx + 1;
        }
        return ans;
    }
}

class Solution {
    public int countNodes(TreeNode root) {
        if (root == null) return 0;

        int leftHeight = getHeight(root.left);
        int rightHeight = getHeight(root.right);

        if (leftHeight == rightHeight) {
            return (1 << leftHeight) + countNodes(root.right);
        } else {
            return (1 << rightHeight) + countNodes(root.left);
        }
    }

    private int getHeight(TreeNode node) {
        int h = 0;
        while (node != null) {
            h++;
            node = node.left;
        }
        return h;
    }

    class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int val) { this.val = val; }
    }
}

import java.util.Arrays;

class Solution {
    public int median(int[][] matrix, int r, int c) {
        int minVal = matrix[0][0];
        int maxVal = matrix[0][c - 1];
        for (int i = 1; i < r; i++) {
            minVal = Math.min(minVal, matrix[i][0]);
            maxVal = Math.max(maxVal, matrix[i][c - 1]);
        }

        int targetCount = (r * c) / 2;
        int ans = maxVal;

        while (minVal <= maxVal) {
            int midVal = minVal + (maxVal - minVal) / 2;
            int count = 0;
            for (int[] row : matrix) {
                int idx = Arrays.binarySearch(row, midVal);
                if (idx < 0) {
                    idx = -(idx + 1);
                } else {
                    while (idx < c && row[idx] == midVal) {
                        idx++;
                    }
                }
                count += idx;
            }

            if (count <= targetCount) {
                minVal = midVal + 1;
            } else {
                ans = midVal;
                maxVal = midVal - 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int bisectLeft(int[] nums, int target) {
        int left = 0;
        int right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public int bisectRight(int[] nums, int target) {
        int left = 0;
        int right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

