class Codec {
    public String serialize(Node root) {
        if (root == null) return "#";
        StringBuilder sb = new StringBuilder();
        sb.append(root.val).append(",").append(root.children.size());
        for (Node child : root.children) {
            sb.append(",").append(serialize(child));
        }
        return sb.toString();
    }

    public Node deserialize(String data) {
        Queue<String> queue = new LinkedList<>(Arrays.asList(data.split(",")));
        return buildTree(queue);
    }

    private Node buildTree(Queue<String> queue) {
        if (queue.isEmpty()) return null;
        String valStr = queue.poll();
        if (valStr.equals("#")) return null;

        Node root = new Node(Integer.parseInt(valStr));
        int numChildren = Integer.parseInt(queue.poll());

        for (int i = 0; i < numChildren; i++) {
            root.children.add(buildTree(queue));
        }
        return root;
    }

    class Node {
        int val;
        List<Node> children;
        Node(int val) { this.val = val; this.children = new ArrayList<>(); }
    }
}

