class Solution {
    public Node findRoot(List<Node> tree) {
        Set<Node> seenChildren = new HashSet<>();
        for (Node node : tree) {
            for (Node child : node.children) {
                seenChildren.add(child);
            }
        }

        for (Node node : tree) {
            if (!seenChildren.contains(node)) {
                return node;
            }
        }
        return null;
    }

