class MagicDictionary {
    class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        boolean isEndOfWord = false;
    }

    private TrieNode root;

    public MagicDictionary() {
        root = new TrieNode();
    }

    public void buildDict(String[] dictionary) {
        for (String word : dictionary) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                node.children.putIfAbsent(c, new TrieNode());
                node = node.children.get(c);
            }
            node.isEndOfWord = true;
        }
    }

    public boolean search(String searchWord) {
        return dfs(root, searchWord, 0, 1);
    }

    private boolean dfs(TrieNode node, String word, int index, int mismatches) {
        if (index == word.length()) {
            return mismatches == 0 && node.isEndOfWord;
        }

        char targetChar = word.charAt(index);

        for (Map.Entry<Character, TrieNode> entry : node.children.entrySet()) {
            char childChar = entry.getKey();
            TrieNode childNode = entry.getValue();

            if (childChar == targetChar) {
                if (dfs(childNode, word, index + 1, mismatches)) {
                    return true;
                }
            } else {
                if (mismatches > 0) {
                    if (dfs(childNode, word, index + 1, mismatches - 1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

