class Solution {
    public boolean isIdentical(Node rootA, Node rootB) {
        if (rootA == null && rootB == null) {
            return true;
        }
        if (rootA == null || rootB == null || rootA.val != rootB.val) {
            return false;
        }
        if (rootA.children.size() != rootB.children.size()) {
            return false;
        }

        for (int i = 0; i < rootA.children.size(); i++) {
            if (!isIdentical(rootA.children.get(i), rootB.children.get(i))) {
                return false;
            }
        }
        return true;
    }

