        List<Node> children;
    }
}

import java.util.List;
import java.util.Collections;

class Solution {
    private int maxDiameter = 0;

    public int diameter(Node root) {
        getHeight(root);
        return maxDiameter;
    }

    private int getHeight(Node node) {
        if (node == null || node.children == null || node.children.isEmpty()) {
            return 0;
        }

        List<Integer> childHeights = new ArrayList<>();
        for (Node child : node.children) {
            childHeights.add(getHeight(child) + 1);
        }
        Collections.sort(childHeights, Collections.reverseOrder());

        int max1 = childHeights.get(0);
        int max2 = childHeights.size() > 1 ? childHeights.get(1) : 0;

        maxDiameter = Math.max(maxDiameter, max1 + max2);

        return max1;
    }

    class Node {
        int val;
        List<Node> children;
    }
}

import java.util.List;

class Solution {
    public Node lowestCommonAncestor(Node root, Node p, Node q) {
        return findLCA(root, p, q);
    }

    private Node findLCA(Node node, Node p, Node q) {
        if (node == null) return null;
        if (node == p || node == q) return node;

        int foundCount = 0;
        Node lcaFromChild = null;

        for (Node child : node.children) {
            Node result = findLCA(child, p, q);
            if (result != null) {
                foundCount++;
                lcaFromChild = result;
            }
        }

        if (foundCount == 2) {
            return node;
        }
        if (foundCount == 1) {
            return lcaFromChild;
        }
        return null;
    }

    class Node {
        int val;
        List<Node> children;
    }
}

