class Solution {
    private int maxDiameter = 0;

    public int diameter(Node root) {
        getHeight(root);
        return maxDiameter;
    }

    private int getHeight(Node node) {
        if (node == null || node.children == null || node.children.isEmpty()) {
            return 0;
        }

        List<Integer> childHeights = new ArrayList<>();
        for (Node child : node.children) {
            childHeights.add(getHeight(child) + 1);
        }
        Collections.sort(childHeights, Collections.reverseOrder());

        int max1 = childHeights.get(0);
        int max2 = childHeights.size() > 1 ? childHeights.get(1) : 0;

        maxDiameter = Math.max(maxDiameter, max1 + max2);

        return max1;
    }

    class Node {
        int val;
        List<Node> children;
    }
}

class Solution {
    private int currentSum = 0;

    public TreeNode bstToGst(TreeNode root) {
        reverseInorder(root);
        return root;
    }

    private void reverseInorder(TreeNode node) {
        if (node == null) return;

        reverseInorder(node.right);

        currentSum += node.val;
        node.val = currentSum;

        reverseInorder(node.left);
    }
}

