class Solution {
    public List<List<Integer>> verticalTraversal(TreeNode root) {
        if (root == null) return new ArrayList<>();
        Map<Integer, List<int[]>> cols = new HashMap<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{root.val, 0, 0});

        Queue<TreeNode> nodeQueue = new LinkedList<>();
        nodeQueue.offer(root);

        int minCol = 0, maxCol = 0;

        while (!nodeQueue.isEmpty()) {
            TreeNode node = nodeQueue.poll();
            int[] info = queue.poll();
            int val = info[0];
            int col = info[1];
            int row = info[2];

            cols.putIfAbsent(col, new ArrayList<>());
            cols.get(col).add(new int[]{row, val});
            minCol = Math.min(minCol, col);
            maxCol = Math.max(maxCol, col);

            if (node.left != null) {
                nodeQueue.offer(node.left);
                queue.offer(new int[]{node.left.val, col - 1, row + 1});
            }
            if (node.right != null) {
                nodeQueue.offer(node.right);
                queue.offer(new int[]{node.right.val, col + 1, row + 1});
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int c = minCol; c <= maxCol; c++) {
            List<int[]> sortedCol = cols.get(c);
            Collections.sort(sortedCol, (a, b) -> {
                if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
                return Integer.compare(a[1], b[1]);
            });
            List<Integer> currentResult = new ArrayList<>();
            for (int[] tuple : sortedCol) {
                currentResult.add(tuple[1]);
            }
            result.add(currentResult);
        }
        return result;
    }
}

class Solution {
    public boolean isValidBST(TreeNode root) {
        return isValid(root, null, null);
    }

    private boolean isValid(TreeNode node, Integer low, Integer high) {
        if (node == null) return true;

        if ((low != null && node.val <= low) || (high != null && node.val >= high)) {
            return false;
        }

        return isValid(node.left, low, node.val) && isValid(node.right, node.val, high);
    }
}

class Solution {
    public TreeNode insertIntoBST(TreeNode root, int val) {
        if (root == null) {
            return new TreeNode(val);
        }

        if (val < root.val) {
            root.left = insertIntoBST(root.left, val);
        } else {
            root.right = insertIntoBST(root.right, val);
        }

        return root;
    }

    class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int val) { this.val = val; }
    }
}

class Solution {
    private TreeNode findMin(TreeNode node) {
        while (node.left != null) {
            node = node.left;
        }
        return node;
    }

    public TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null;

        if (key < root.val) {
            root.left = deleteNode(root.left, key);
        } else if (key > root.val) {
            root.right = deleteNode(root.right, key);
        } else {
            if (root.left == null) {
                return root.right;
            } else if (root.right == null) {
                return root.left;
            } else {
                TreeNode successor = findMin(root.right);
                root.val = successor.val;
                root.right = deleteNode(root.right, successor.val);
            }
        }
        return root;
    }
}

import java.util.List;
