class Solution {
    public boolean isCompleteTree(TreeNode root) {
        if (root == null) return true;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        boolean foundNull = false;

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();

            if (node == null) {
                foundNull = true;
            } else {
                if (foundNull) {
                    return false;
                }
                queue.offer(node.left);
                queue.offer(node.right);
            }
        }
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;
import java.util.PriorityQueue;
import java.util.Comparator;
import java.util.Collections;

class AutocompleteSystem {
    class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        Map<String, Integer> freqs = new HashMap<>();
    }

    private TrieNode root;
    private TrieNode currNode;
    private String prefix;

    public AutocompleteSystem(String[] sentences, int[] times) {
        root = new TrieNode();
        currNode = root;
        prefix = "";
        for (int i = 0; i < sentences.length; i++) {
            addSentence(sentences[i], times[i]);
        }
    }

    private void addSentence(String s, int t) {
        TrieNode node = root;
        for (char c : s.toCharArray()) {
            node.children.putIfAbsent(c, new TrieNode());
            node = node.children.get(c);
            node.freqs.put(s, node.freqs.getOrDefault(s, 0) + t);
        }
    }

    public List<String> input(char c) {
        if (c == '#') {
            addSentence(prefix, 1);
            prefix = "";
            currNode = root;
            return new ArrayList<>();
        }

        prefix += c;
        if (currNode == null) {
            return new ArrayList<>();
        }
        currNode = currNode.children.get(c);

        if (currNode == null) {
            return new ArrayList<>();
        }

        PriorityQueue<Map.Entry<String, Integer>> maxHeap = new PriorityQueue<>(
            (a, b) -> {
                if (a.getValue() != b.getValue()) return a.getValue() - b.getValue();
                return b.getKey().compareTo(a.getKey());
            }
        );

        for (Map.Entry<String, Integer> entry : currNode.freqs.entrySet()) {
            maxHeap.offer(entry);
            if (maxHeap.size() > 3) maxHeap.poll();
        }

        List<String> result = new ArrayList<>();
        while (!maxHeap.isEmpty()) {
            result.add(maxHeap.poll().getKey());
        }
        Collections.reverse(result);
        return result;
    }
}

import java.util.Queue;
import java.util.LinkedList;

class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{root.val, 0});
        Queue<TreeNode> nodeQueue = new LinkedList<>();
        nodeQueue.offer(root);
        long maxWidth = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            long minIndex = queue.peek()[1];
            long maxIndex = queue.peek()[1];

            for (int i = 0; i < levelSize; i++) {
                int[] info = queue.poll();
                TreeNode node = nodeQueue.poll();
                long index = info[1];

                if (i == levelSize - 1) maxIndex = index;

                if (node.left != null) {
                    nodeQueue.offer(node.left);
                    queue.offer(new int[]{node.left.val, (int)(2 * (index - minIndex) + 1)});
                }
                if (node.right != null) {
                    nodeQueue.offer(node.right);
                    queue.offer(new int[]{node.right.val, (int)(2 * (index - minIndex) + 2)});
                }
            }
            maxWidth = Math.max(maxWidth, maxIndex - minIndex + 1);
        }
        return (int)maxWidth;
    }
}

