class Solution {
    public Node lowestCommonAncestor(Node p, Node q) {
        Set<Node> ancestorsP = new HashSet<>();
        Node curr = p;
        while (curr != null) {
            ancestorsP.add(curr);
            curr = curr.parent;
        }

        curr = q;
        while (curr != null) {
            if (ancestorsP.contains(curr)) {
                return curr;
            }
            curr = curr.parent;
        }
        return null;
    }

    class Node {
        int val;
        Node left;
        Node right;
        Node parent;
    }
}

class Solution {
    private Node first = null;
    private Node last = null;

    public Node treeToDoublyList(Node root) {
        if (root == null) return null;
        inorder(root);
        last.right = first;
        first.left = last;
        return first;
    }

    private void inorder(Node node) {
        if (node == null) return;

        inorder(node.left);

        if (first == null) {
            first = node;
        }
        if (last != null) {
            last.right = node;
            node.left = last;
        }
        last = node;

        inorder(node.right);
    }

    class Node {
        int val;
        Node left;
        Node right;
    }
}

