class Solution {
    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        Map<String, Integer> subtreeCounts = new HashMap<>();
        List<TreeNode> duplicates = new ArrayList<>();
        postorderSerialize(root, subtreeCounts, duplicates);
        return duplicates;
    }

    private String postorderSerialize(TreeNode node, Map<String, Integer> subtreeCounts, List<TreeNode> duplicates) {
        if (node == null) return "#";

        String s = node.val + "," + postorderSerialize(node.left, subtreeCounts, duplicates) + "," + postorderSerialize(node.right, subtreeCounts, duplicates);

        subtreeCounts.put(s, subtreeCounts.getOrDefault(s, 0) + 1);
        if (subtreeCounts.get(s) == 2) {
            duplicates.add(node);
        }
        return s;
    }
}

class Solution {
    private Long prevVal = Long.MIN_VALUE;

    public boolean isValidBST(TreeNode root) {
        if (root == null) return true;

        if (!isValidBST(root.left)) return false;

        if (root.val <= prevVal) return false;
        prevVal = (long) root.val;

        return isValidBST(root.right);
    }
}

class Solution {
    public Node connect(Node root) {
        if (root == null || root.left == null) return root;

        root.left.next = root.right;

        if (root.next != null) {
            root.right.next = root.next.left;
        }

        connect(root.left);
        connect(root.right);
        return root;
    }

    class Node {
        int val;
        Node left;
        Node right;
        Node next;
    }
}

import java.util.Queue;
import java.util.LinkedList;

class Solution {
    public Node connect(Node root) {
        if (root == null) return null;
        Queue<Node> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            Node prev = null;
            for (int i = 0; i < levelSize; i++) {
                Node node = queue.poll();
                if (prev != null) {
                    prev.next = node;
                }
                prev = node;

                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
        }
        return root;
    }

    class Node {
        int val;
        Node left;
        Node right;
        Node next;
    }
}

class Solution {
    private int ROWS, COLS;
    private final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int numIslands(char[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        ROWS = grid.length;
        COLS = grid[0].length;
        int islandCount = 0;

        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                if (grid[r][c] == '1') {
                    islandCount++;
                    dfs(grid, r, c);
                }
            }
        }
        return islandCount;
    }

    private void dfs(char[][] grid, int r, int c) {
        if (r < 0 || r >= ROWS || c < 0 || c >= COLS || grid[r][c] == '0') {
            return;
        }

        grid[r][c] = '0';
        for (int[] dir : DIRS) {
            dfs(grid, r + dir[0], c + dir[1]);
        }
    }
}

