        for (int i = 0; i < n; i++) {
            count += expandAndCount(s, i, i);
            count += expandAndCount(s, i, i + 1);
        }
        return count;
    }

    private int expandAndCount(String s, int left, int right) {
        int count = 0;
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            count++;
            left--;
            right++;
        }
        return count;
    }
}

