class Solution {
    public int minDeletions(String s) {
        Map<Character, Integer> freqCounts = new HashMap<>();
        for (char c : s.toCharArray()) {
            freqCounts.put(c, freqCounts.getOrDefault(c, 0) + 1);
        }

        int deletions = 0;
        Set<Integer> seenFrequencies = new HashSet<>();

        for (int freq : freqCounts.values()) {
            while (freq > 0 && seenFrequencies.contains(freq)) {
                freq--;
                deletions++;
            }
            if (freq > 0) {
                seenFrequencies.add(freq);
            }
        }
        return deletions;
    }
}

