import java.util.Stack;

class Solution {
    class Pair {
        char character;
        int count;
        Pair(char character, int count) {
            this.character = character;
            this.count = count;
        }
    }

    public String removeDuplicates(String s, int k) {
        Stack<Pair> stack = new Stack<>();
        for (char c : s.toCharArray()) {
            if (!stack.isEmpty() && stack.peek().character == c) {
                stack.peek().count++;
            } else {
                stack.push(new Pair(c, 1));
            }

            if (!stack.isEmpty() && stack.peek().count == k) {
                stack.pop();
            }
        }

        StringBuilder result = new StringBuilder();
        for (Pair p : stack) {
            for (int i = 0; i < p.count; i++) {
                result.append(p.character);
            }
        }
        return result.toString();
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class Solution {
    public String reorganizeString(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) {
            counts.put(c, counts.getOrDefault(c, 0) + 1);
        }

        PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > (s.length() + 1) / 2) return "";
            maxHeap.offer(new int[] {entry.getValue(), entry.getKey()});
        }

        StringBuilder result = new StringBuilder();
        int[] prev = {0, ' '};

        while (!maxHeap.isEmpty()) {
            int[] current = maxHeap.poll();

            if (prev[0] > 0) {
                maxHeap.offer(prev);
            }

            result.append((char)current[1]);
            current[0]--;
            prev = current;
        }

        return result.toString();
    }
}

class Solution {
    public int longestCommonSubstring(String text1, String text2) {
        int m = text1.length();
        int n = text2.length();
        int[][] dp = new int[m + 1][n + 1];
        int maxLen = 0;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                    maxLen = Math.max(maxLen, dp[i][j]);
                } else {
                    dp[i][j] = 0;
                }
            }
        }
        return maxLen;
    }
}

class Solution {
