class Solution {
    public int strStr(String haystack, String needle) {
        int n = haystack.length(), m = needle.length();
        if (m == 0) return 0;
        if (m > n) return -1;

        long BASE = 26;
        long MOD = 1000000007;
        long needleHash = 0;
        long currentHash = 0;
        long power = 1;

        for (int i = 0; i < m; i++) {
            needleHash = (needleHash * BASE + (needle.charAt(i) - 'a')) % MOD;
            currentHash = (currentHash * BASE + (haystack.charAt(i) - 'a')) % MOD;
            if (i < m - 1) {
                power = (power * BASE) % MOD;
            }
        }

        if (needleHash == currentHash && haystack.substring(0, m).equals(needle)) return 0;

        for (int i = 1; i <= n - m; i++) {
            currentHash = (currentHash - (haystack.charAt(i - 1) - 'a') * power) % MOD;
            currentHash = (currentHash * BASE + (haystack.charAt(i + m - 1) - 'a')) % MOD;

            if (currentHash < 0) currentHash += MOD;

            if (needleHash == currentHash && haystack.substring(i, i + m).equals(needle)) return i;
        }
        return -1;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    private long BASE = 26;
    private long MOD = 1000000007;

    public String longestDupSubstring(String s) {
        int n = s.length();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = s.charAt(i) - 'a';
        }

        int left = 1, right = n;
        int start = -1, maxLen = 0;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            int index = check(mid, nums, s);

            if (index != -1) {
                maxLen = mid;
                start = index;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return start == -1 ? "" : s.substring(start, start + maxLen);
    }

    private int check(int L, int[] nums, String s) {
        long power = 1;
        for (int i = 0; i < L; i++) {
            power = (power * BASE) % MOD;
        }

        long currentHash = 0;
        for (int i = 0; i < L; i++) {
            currentHash = (currentHash * BASE + nums[i]) % MOD;
        }

        Set<Long> seen = new HashSet<>();
        seen.add(currentHash);

        for (int i = 1; i <= nums.length - L; i++) {
            currentHash = (currentHash * BASE - nums[i - 1] * power) % MOD;
            currentHash = (currentHash + nums[i + L - 1]) % MOD;
            if (currentHash < 0) currentHash += MOD;

            if (seen.contains(currentHash)) {
                return i;
            }
            seen.add(currentHash);
        }
        return -1;
    }
}

