    }
}

class Solution {
    private void reverse(int[] nums, int start) {
        int end = nums.length - 1;
        while (start < end) {
            int temp = nums[start];
            nums[start] = nums[end];
            nums[end] = temp;
            start++;
            end--;
        }
    }
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) {
            i--;
        }
        if (i == -1) {
            reverse(nums, 0);
            return;
        }
        int j = n - 1;
        while (nums[j] <= nums[i]) {
            j--;
        }
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
        reverse(nums, i + 1);
    }
}

class Solution {
    public boolean canJump(int[] nums) {
        int maxReach = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if (i > maxReach) {
                return false;
            }
            maxReach = Math.max(maxReach, i + nums[i]);
            if (maxReach >= n - 1) {
                return true;
            }
        }
        return true;
    }
}

class Solution {
    public int jump(int[] nums) {
        int jumps = 0;
        int currentFarthest = 0;
        int nextFarthest = 0;
        int n = nums.length;
        for (int i = 0; i < n - 1; i++) {
            nextFarthest = Math.max(nextFarthest, i + nums[i]);
            if (i == currentFarthest) {
                jumps++;
                currentFarthest = nextFarthest;
            }
        }
        return jumps;
    }
}

