import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<Integer> majorityElement(int[] nums) {
        if (nums == null || nums.length == 0) return new ArrayList<>();

        Integer v1 = null, v2 = null;
        int c1 = 0, c2 = 0;

        for (int num : nums) {
            if (v1 != null && num == v1) {
                c1++;
            } else if (v2 != null && num == v2) {
                c2++;
            } else if (c1 == 0) {
                v1 = num;
                c1 = 1;
            } else if (c2 == 0) {
                v2 = num;
                c2 = 1;
            } else {
                c1--;
                c2--;
            }
        }

        c1 = 0;
        c2 = 0;
        for (int num : nums) {
            if (v1 != null && num == v1) c1++;
            if (v2 != null && num == v2) c2++;
        }

        List<Integer> result = new ArrayList<>();
        int n = nums.length;
        if (v1 != null && c1 > n / 3) result.add(v1);
        if (v2 != null && c2 > n / 3 && !result.contains(v2)) result.add(v2);

        return result;
    }
}

