class Solution {
    public int findKthLargest(int[] nums, int k) {
        int kSmallestIdx = nums.length - k;
        return quickSelect(nums, 0, nums.length - 1, kSmallestIdx);
    }

    private int quickSelect(int[] nums, int left, int right, int kSmallestIdx) {
        if (left == right) {
            return nums[left];
        }
        int pivotIdx = partition(nums, left, right);
        if (pivotIdx == kSmallestIdx) {
            return nums[pivotIdx];
        } else if (pivotIdx < kSmallestIdx) {
            return quickSelect(nums, pivotIdx + 1, right, kSmallestIdx);
        } else {
            return quickSelect(nums, left, pivotIdx - 1, kSmallestIdx);
        }
    }

    private int partition(int[] nums, int left, int right) {
        int pivotVal = nums[right];
        int storeIdx = left;
        for (int i = left; i < right; i++) {
            if (nums[i] <= pivotVal) {
                swap(nums, storeIdx, i);
                storeIdx++;
            }
        }
        swap(nums, storeIdx, right);
        return storeIdx;
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        int left = 0;
        int right = n - 1;
        int pWrite = n - 1;
        while (left <= right) {
            if (Math.abs(nums[left]) > Math.abs(nums[right])) {
                result[pWrite] = nums[left] * nums[left];
                left++;
            } else {
                result[pWrite] = nums[right] * nums[right];
                right--;
            }
            pWrite--;
        }
        return result;
    }
}

