class Solution {
    public int lengthOfLIS(int[] nums) {
        List<Integer> sub = new ArrayList<>();
        for (int num : nums) {
            if (sub.isEmpty() || num > sub.get(sub.size() - 1)) {
                sub.add(num);
            } else {
                int idx = bisectLeft(sub, num);
                sub.set(idx, num);
            }
        }
        return sub.size();
    }

    private int bisectLeft(List<Integer> list, int target) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (list.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

import java.util.Arrays;

class Solution {
    public int coinChange(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;

        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (i - coin >= 0) {
                    dp[i] = Math.min(dp[i], 1 + dp[i - coin]);
                }
            }
        }

        return (dp[amount] > amount) ? -1 : dp[amount];
    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    class Job {
        int start, end, profit;
        Job(int s, int e, int p) {
            this.start = s;
            this.end = e;
            this.profit = p;
        }
    }

    int n;
    Job[] jobs;
    Map<Integer, Integer> memo = new HashMap<>();
    int[] sortedStartTimes;

    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        n = startTime.length;
        jobs = new Job[n];
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(startTime[i], endTime[i], profit[i]);
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a.start, b.start));

        sortedStartTimes = new int[n];
        for(int i=0; i<n; i++) sortedStartTimes[i] = jobs[i].start;

        return dp(0);
    }

    private int dp(int i) {
        if (i == n) return 0;
        if (memo.containsKey(i)) return memo.get(i);

        int profitSkip = dp(i + 1);

        int currentEndTime = jobs[i].end;

        int nextJobIndex = Arrays.binarySearch(sortedStartTimes, currentEndTime);
        if (nextJobIndex < 0) {
            nextJobIndex = -(nextJobIndex + 1);
        }

        int profitTake = jobs[i].profit + dp(nextJobIndex);

        int maxProfit = Math.max(profitSkip, profitTake);
        memo.put(i, maxProfit);
        return maxProfit;
    }
}

