class Solution {
    public int longSubarrWthSumDivByK(int arr[], int n, int k) {
        Map<Integer, Integer> remainderMap = new HashMap<>();
        remainderMap.put(0, -1);
        int currentSum = 0;
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            currentSum += arr[i];
            int remainder = (currentSum % k + k) % k;

            if (remainderMap.containsKey(remainder)) {
                maxLen = Math.max(maxLen, i - remainderMap.get(remainder));
            } else {
                remainderMap.put(remainder, i);
            }
        }
        return maxLen;
    }
}

class Solution {
    private int bisectRight(int[] row, int target) {
        int left = 0;
        int right = row.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (row[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    public int median(int[][] matrix, int r, int c) {
        int minVal = matrix[0][0];
        int maxVal = matrix[0][c - 1];
        for (int i = 1; i < r; i++) {
            minVal = Math.min(minVal, matrix[i][0]);
            maxVal = Math.max(maxVal, matrix[i][c - 1]);
        }

        int targetCount = (r * c) / 2;
        int ans = maxVal;

        while (minVal <= maxVal) {
            int midVal = minVal + (maxVal - minVal) / 2;
            int count = 0;
            for (int i = 0; i < r; i++) {
                count += bisectRight(matrix[i], midVal);
            }

            if (count <= targetCount) {
                minVal = midVal + 1;
            } else {
                ans = midVal;
                maxVal = midVal - 1;
            }
        }
        return ans;
    }
}

