import java.util.HashSet;
import java.util.Set;

class Solution {
    public boolean isValidSudoku(char[][] board) {
        Set<Character>[] rows = new HashSet[9];
        Set<Character>[] cols = new HashSet[9];
        Set<Character>[] boxes = new HashSet[9];
        for (int i = 0; i < 9; i++) {
            rows[i] = new HashSet<>();
            cols[i] = new HashSet<>();
            boxes[i] = new HashSet<>();
        }

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                char val = board[r][c];
                if (val == '.') {
                    continue;
                }
                int boxIdx = (r / 3) * 3 + (c / 3);

                if (rows[r].contains(val) || cols[c].contains(val) || boxes[boxIdx].contains(val)) {
                    return false;
                }

                rows[r].add(val);
                cols[c].add(val);
                boxes[boxIdx].add(val);
            }
        }
        return true;
    }
}

class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int totalGas = 0;
        int totalCost = 0;
        for (int g : gas) totalGas += g;
        for (int c : cost) totalCost += c;
        if (totalGas < totalCost) {
            return -1;
        }

        int totalTank = 0;
        int startIndex = 0;
        for (int i = 0; i < gas.length; i++) {
            totalTank += gas[i] - cost[i];
            if (totalTank < 0) {
                totalTank = 0;
                startIndex = i + 1;
            }
        }
        return startIndex;
    }
}

import java.util.Arrays;

class Solution {
    public int findMinArrowShots(int[][] points) {
        if (points.length == 0) return 0;

        Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));

        int arrows = 1;
        int firstEnd = points[0][1];

        for (int i = 1; i < points.length; i++) {
            if (points[i][0] > firstEnd) {
                arrows++;
                firstEnd = points[i][1];
            }
        }
        return arrows;
    }
}

import java.util.Arrays;

class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        if (intervals.length == 0) return 0;

        Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));

        int count = 1;
        int lastEnd = intervals[0][1];

        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] >= lastEnd) {
                count++;
                lastEnd = intervals[i][1];
            }
        }
        return intervals.length - count;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public int[][] intervalIntersection(int[][] firstList, int[][] secondList) {
        List<int[]> result = new ArrayList<>();
        int i = 0, j = 0;
        int m = firstList.length, n = secondList.length;

        while (i < m && j < n) {
            int start1 = firstList[i][0], end1 = firstList[i][1];
            int start2 = secondList[j][0], end2 = secondList[j][1];

            int intersectionStart = Math.max(start1, start2);
            int intersectionEnd = Math.min(end1, end2);

            if (intersectionStart <= intersectionEnd) {
                result.add(new int[] { intersectionStart, intersectionEnd });
            }

            if (end1 < end2) {
                i++;
            } else {
                j++;
            }
        }
        return result.toArray(new int[result.size()][]);
    }
}

class Solution {
    public int rob(int[] nums) {
        int rob1 = 0;
        int rob2 = 0;

        for (int num : nums) {
            int temp = Math.max(rob1 + num, rob2);
            rob1 = rob2;
            rob2 = temp;
        }
        return rob2;
    }
}

import java.util.Arrays;

class Solution {
    private int robLinear(int[] nums) {
        int rob1 = 0;
        int rob2 = 0;
        for (int num : nums) {
            int temp = Math.max(rob1 + num, rob2);
            rob1 = rob2;
            rob2 = temp;
        }
        return rob2;
    }

    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 1) {
            return nums[0];
        }

        int[] sub1 = Arrays.copyOfRange(nums, 0, n - 1);
        int case1 = robLinear(sub1);

        int[] sub2 = Arrays.copyOfRange(nums, 1, n);
        int case2 = robLinear(sub2);

        return Math.max(case1, case2);
    }
}

class Solution {
    public int climbStairs(int n) {
        if (n <= 2) return n;
        int twoStepsBack = 1;
        int oneStepBack = 2;
        int current = 0;
        for (int i = 3; i <= n; i++) {
            current = twoStepsBack + oneStepBack;
            twoStepsBack = oneStepBack;
            oneStepBack = current;
        }
        return oneStepBack;
    }
}

