def findTargetSumWays(nums, target):
    total_sum = sum(nums)
    if (total_sum + target) % 2 != 0 or total_sum < abs(target): return 0
    s = (total_sum + target) // 2
    dp = [0] * (s + 1)
    dp[0] = 1
