def minimumDeleteSum(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    # dp[i][j] is the maximum ASCII sum of common subsequence of s1[:i] and s2[:j]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = ord(s1[i-1]) + dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    lcs_ascii_sum = dp[m][n]
    total_ascii_sum = sum(ord(c) for c in s1) + sum(ord(c) for c in s2)
    return total_ascii_sum - 2 * lcs_ascii_sum

