def isScramble(s1, s2):
    n = len(s1)
    if n != len(s2) or sorted(s1) != sorted(s2): return False
    memo = {}
    def solve(i, j, length):
        if length == 1: return s1[i] == s2[j]
        if (i, j, length) in memo: return memo[(i, j, length)]

        for k in range(1, length):
            # Case 1: No swap
            if (solve(i, j, k) and solve(i + k, j + k, length - k)):
                memo[(i, j, length)] = True
                return True
            # Case 2: Swap
            if (solve(i, j + length - k, k) and solve(i + k, j, length - k)):
                memo[(i, j, length)] = True
                return True

        memo[(i, j, length)] = False
        return False

    return solve(0, 0, n)

