import java.util.HashMap;
import java.util.Map;
import java.util.Arrays;
import java.util.Collections;

class Solution {
    private Map<String, Boolean> memo = new HashMap<>();

    public boolean isScramble(String s1, String s2) {
        int n = s1.length();
        if (n != s2.length()) return false;

        char[] arr1 = s1.toCharArray();
        char[] arr2 = s2.toCharArray();
        Arrays.sort(arr1);
        Arrays.sort(arr2);
        if (!Arrays.equals(arr1, arr2)) return false;

        return solve(s1, s2, 0, 0, n);
    }

    private boolean solve(String s1, String s2, int i, int j, int length) {
        if (length == 1) return s1.charAt(i) == s2.charAt(j);

        String key = i + "," + j + "," + length;
        if (memo.containsKey(key)) return memo.get(key);

        for (int k = 1; k < length; k++) {
            boolean noSwap = solve(s1, s2, i, j, k) && solve(s1, s2, i + k, j + k, length - k);
            if (noSwap) {
                memo.put(key, true);
                return true;
            }

            boolean swap = solve(s1, s2, i, j + length - k, k) && solve(s1, s2, i + k, j, length - k);
            if (swap) {
                memo.put(key, true);
                return true;
            }
        }

        memo.put(key, false);
        return false;
    }
}

