class Solution {
    public int countVowelPermutation(int n) {
        long MOD = 1000000000 + 7;
        long a = 1, e = 1, i = 1, o = 1, u = 1;

        for (int k = 2; k <= n; k++) {
            long aNew = (e + i + u) % MOD;
            long eNew = (a + i) % MOD;
            long iNew = (e + o) % MOD;
            long oNew = (i) % MOD;
            long uNew = (i + o) % MOD;
            a = aNew; e = eNew; i = iNew; o = oNew; u = uNew;
        }

        return (int) ((a + e + i + o + u) % MOD);
    }
}

