def minCut(s):
    n = len(s)
    cuts = [i - 1 for i in range(n + 1)] # cuts[i] = min cuts for s[i:]
    is_palindrome = [[False] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i < 2 or is_palindrome[i + 1][j - 1]):
                is_palindrome[i][j] = True
                # If s[i:j+1] is a palindrome, cuts[i] is either its current value or
                # 1 cut (at j) + min cuts for the remaining string s[j+1:]
                cuts[i] = min(cuts[i], cuts[j + 1] + 1)

    return cuts[0]

