class Solution {
    public int change(int amount, int[] coins) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;
        for (int coin : coins) {
            for (int x = coin; x <= amount; x++) {
                dp[x] += dp[x - coin];
            }
        }
        return dp[amount];
    }
}

import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        int R = dungeon.length;
        int C = dungeon[0].length;
        int INF = Integer.MAX_VALUE;
        int[][] dp = new int[R + 1][C + 1];

        for (int i = 0; i <= R; i++) Arrays.fill(dp[i], INF);
        dp[R][C - 1] = 1;
        dp[R - 1][C] = 1;

        for (int r = R - 1; r >= 0; r--) {
            for (int c = C - 1; c >= 0; c--) {
                int minExitHealth = Math.min(dp[r + 1][c], dp[r][c + 1]);
                int requiredEnterHealth = minExitHealth - dungeon[r][c];
                dp[r][c] = Math.max(1, requiredEnterHealth);
            }
        }

        return dp[0][0];
    }
}

import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int minSwap(int[] A, int[] B) {
        int n = A.length;
        int[] swap = new int[n];
        int[] noSwap = new int[n];
        Arrays.fill(swap, Integer.MAX_VALUE);
        Arrays.fill(noSwap, Integer.MAX_VALUE);

        swap[0] = 1;
        noSwap[0] = 0;

        for (int i = 1; i < n; i++) {
            boolean condition1 = (A[i-1] < A[i] && B[i-1] < B[i]);
            boolean condition2 = (A[i-1] < B[i] && B[i-1] < A[i]);

            if (condition1) {
                noSwap[i] = noSwap[i-1];
                swap[i] = swap[i-1] + 1;
            }

            if (condition2) {
                noSwap[i] = Math.min(noSwap[i], swap[i-1]);
                swap[i] = Math.min(swap[i], noSwap[i-1] + 1);
            }
        }

        return Math.min(swap[n-1], noSwap[n-1]);
    }
}

