import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[][] dp = new int[m + 1][n + 1];

        for (int i = 0; i <= m; i++) dp[i][0] = i;
        for (int j = 0; j <= n; j++) dp[0][j] = j;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1.charAt(i-1) == word2.charAt(j-1)) {
                    dp[i][j] = dp[i-1][j-1];
                } else {
                    dp[i][j] = 1 + Math.min(dp[i-1][j], 
                                            Math.min(dp[i][j-1], 
                                                     dp[i-1][j-1]));
                }
            }
        }
        return dp[m][n];
    }
}

import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int numSubseq(int[] nums, int target) {
        int MOD = 1000000007;
        Arrays.sort(nums);
        int n = nums.length;

        int[] powersOf2 = new int[n];
        powersOf2[0] = 1;
        for (int i = 1; i < n; i++) {
            powersOf2[i] = (powersOf2[i-1] * 2) % MOD;
        }

        int left = 0;
        int right = n - 1;
        long count = 0;

        while (left <= right) {
            if (nums[left] + nums[right] <= target) {
                count = (count + powersOf2[right - left]) % MOD;
                left++;
            } else {
                right--;
            }
        }

        return (int) count;
    }
}

import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int mergeStones(int[] piles, int K) {
        int n = piles.length;
        if ((n - 1) % (K - 1) != 0) return -1;
        if (K != 2) return -1;

        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) prefixSum[i+1] = prefixSum[i] + piles[i];

        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[n][n];

        for (int length = 2; length <= n; length++) {
            for (int i = 0; i <= n - length; i++) {
                int j = i + length - 1;
                dp[i][j] = INF;
                for (int k = i; k < j; k++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k+1][j]);
                }
                dp[i][j] += prefixSum[j+1] - prefixSum[i];
            }
        }
        return dp[0][n-1];
    }
}

import java.lang.Math;

class Solution {
    public int countVowelPermutation(int n) {
        long MOD = 1000000000 + 7;
        long a = 1, e = 1, i = 1, o = 1, u = 1;

        for (int k = 2; k <= n; k++) {
            long aNew = (e + i + u) % MOD;
            long eNew = (a + i) % MOD;
            long iNew = (e + o) % MOD;
            long oNew = (i) % MOD;
            long uNew = (i + o) % MOD;
            a = aNew; e = eNew; i = iNew; o = oNew; u = uNew;
        }

        return (int) ((a + e + i + o + u) % MOD);
    }
}

