def splitArray(nums, k):
    def is_possible(max_sum):
        num_subarrays = 1
        current_sum = 0
        for num in nums:
            if current_sum + num <= max_sum:
                current_sum += num
            else:
                num_subarrays += 1
                current_sum = num
                if num_subarrays > k: return False
        return True

    low = max(nums)
    high = sum(nums)
    result = high

    while low <= high:
        mid = low + (high - low) // 2
        if is_possible(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

