import java.util.Arrays;
import java.lang.Math;

class Solution {
    public int splitArray(int[] nums, int k) {
        long low = 0;
        long high = 0;
        for (int num : nums) {
            low = Math.max(low, num);
            high += num;
        }
        long result = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (isPossible(nums, k, mid)) {
                result = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return (int) result;
    }

    private boolean isPossible(int[] nums, int k, long maxSum) {
        int numSubarrays = 1;
        long currentSum = 0;
        for (int num : nums) {
            if (currentSum + num <= maxSum) {
                currentSum += num;
            } else {
                numSubarrays++;
                currentSum = num;
            }
        }
        return numSubarrays <= k;
    }
}
